package com.plugandplant;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Supplier;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.FontID;
import net.runelite.api.ScriptEvent;
import net.runelite.api.ScriptID;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.SoundEffectID;
import net.runelite.api.gameval.SpriteID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.plugins.banktags.BankTagsService;
import net.runelite.client.plugins.banktags.TagManager;
import net.runelite.client.plugins.banktags.tabs.LayoutManager;

/**
 * Filters the bank down to farm run items by way of a Bank Tags tag, places them in sections with a
 * heading over each, and adds a button to the bank to turn it on and off. All methods run on the
 * client thread.
 *
 * The items are placed by moving their widgets after the bank is built, rather than through a Bank
 * Tags layout, because layout plugins such as Bank Tag Layouts take over the layout of every tag.
 */
@Singleton
class BankFilter
{
	/**
	 * Also searchable in the bank as "tag:plug-and-plant". Bank Tags merges a player's own tag of the
	 * same name into the filter, so the name is specific to this plugin.
	 */
	static final String TAG = "plug-and-plant";

	private static final String BANK_TAGS_GROUP = "banktags";
	/**
	 * The Bank Tags setting that remembers the open tag, to reopen it the next time the bank opens.
	 */
	private static final String REMEMBERED_TAB_KEY = "tab";
	private static final int OPEN_OPTIONS = BankTagsService.OPTION_HIDE_TAG_NAME | BankTagsService.OPTION_NO_LAYOUT;
	/**
	 * Layout plugins run at -1 to come after Bank Tags; this comes after them.
	 */
	private static final float AFTER_LAYOUT_PLUGINS = -2f;

	private static final int ROW_HEIGHT = BankTagsPlugin.BANK_ITEM_HEIGHT + BankTagsPlugin.BANK_ITEM_Y_PADDING;
	private static final int COLUMN_WIDTH = BankTagsPlugin.BANK_ITEM_WIDTH + BankTagsPlugin.BANK_ITEM_X_PADDING;
	private static final int ROW_WIDTH = BankTagsPlugin.BANK_ITEMS_PER_ROW * COLUMN_WIDTH;
	private static final int HEADING_HEIGHT = 15;
	private static final int HEADING_COLOR = 0xE4D8A2;

	// The button sits left of where Quest Helper puts its own, so the two don't overlap
	private static final int BUTTON_SIZE = 25;
	private static final int BUTTON_X = 378;
	private static final int BUTTON_Y = 5;
	private static final String BUTTON_ACTION = "Toggle farm run items";

	private final Client client;
	private final ClientThread clientThread;
	private final ConfigManager configManager;
	private final TagManager tagManager;
	private final BankTagsService bankTagsService;
	private final LayoutManager layoutManager;
	private final ItemManager itemManager;
	private final PluginManager pluginManager;

	private BankFilterSpec spec = BankFilterSpec.EMPTY;
	/**
	 * What the player has listed to always show, and to never show, whatever the run needs.
	 */
	private ItemList alwaysShown = ItemList.EMPTY;
	private ItemList neverShown = ItemList.EMPTY;
	/**
	 * Canonical item id to bank slot, worked out once per bank visit so items stay put as they are
	 * withdrawn; null until the filter is first shown on this visit.
	 */
	@Nullable
	private Map<Integer, Integer> slots;
	/**
	 * Where the headings go.
	 */
	private Map<BankSection, Integer> headingRows = Map.of();
	/**
	 * Heading widgets added to the bank's item container, kept to be reused each time the bank is rebuilt.
	 */
	private final List<Widget> headingWidgets = new ArrayList<>();
	@Nullable
	private Widget buttonBackground;
	@Nullable
	private Widget buttonIcon;
	/**
	 * Open the filter once the bank has been built.
	 */
	private boolean openRequested;

	@Inject
	BankFilter(Client client, ClientThread clientThread, ConfigManager configManager, TagManager tagManager,
		BankTagsService bankTagsService, LayoutManager layoutManager, ItemManager itemManager, PluginManager pluginManager)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.configManager = configManager;
		this.tagManager = tagManager;
		this.bankTagsService = bankTagsService;
		this.layoutManager = layoutManager;
		this.itemManager = itemManager;
		this.pluginManager = pluginManager;
	}

	void register()
	{
		tagManager.registerTag(TAG, this::shows);
		// An earlier version saved a Bank Tags layout for the tag, which would now get in the way
		layoutManager.removeLayout(TAG);
		if (client.getWidget(InterfaceID.Bankmain.UNIVERSE) != null)
		{
			createButton();
		}
	}

	void unregister()
	{
		close();
		tagManager.unregisterTag(TAG);
		headingRows = Map.of();
		drawHeadings();
		for (Widget widget : new Widget[]{buttonBackground, buttonIcon})
		{
			if (widget != null)
			{
				widget.setHidden(true);
			}
		}
		buttonBackground = buttonIcon = null;
	}

	/**
	 * Takes effect the next time the filter is opened.
	 */
	void setSpec(BankFilterSpec spec)
	{
		this.spec = spec;
	}

	/**
	 * Takes the player's own lists, and shows the filter afresh if it is open so the change is seen.
	 */
	void setItemLists(ItemList alwaysShown, ItemList neverShown)
	{
		if (alwaysShown.equals(this.alwaysShown) && neverShown.equals(this.neverShown))
		{
			return;
		}
		this.alwaysShown = alwaysShown;
		this.neverShown = neverShown;
		if (isOpen())
		{
			open();
		}
	}

	boolean isAvailable()
	{
		return bankTagsPlugin() != null;
	}

	boolean isOpen()
	{
		return isAvailable() && TAG.equals(bankTagsService.getActiveTag());
	}

	boolean isBankOpen()
	{
		return client.getWidget(InterfaceID.Bankmain.ITEMS) != null;
	}

	/**
	 * Opens the filter once the bank that is opening has been built.
	 */
	void openWhenBuilt()
	{
		openRequested = true;
	}

	/**
	 * Shows the filter, arranged afresh.
	 */
	void open()
	{
		openRequested = false;
		if (!isBankOpen() || !isAvailable())
		{
			return;
		}

		slots = null;
		// Leave a vanilla tab or the potion store, as Bank Tags' own tabs do
		client.setVarbit(VarbitID.BANK_CURRENTTAB, 0);
		bankTagsService.openBankTag(TAG, OPEN_OPTIONS);
	}

	/**
	 * Closes the filter, unless the player has since moved to another tag.
	 */
	void close()
	{
		openRequested = false;
		if (isOpen())
		{
			bankTagsService.closeBankTag();
		}
		// With the bank shut there is no open tag to close, but Bank Tags may still mean to reopen this one
		if (TAG.equals(configManager.getConfiguration(BANK_TAGS_GROUP, REMEMBERED_TAB_KEY)))
		{
			configManager.setConfiguration(BANK_TAGS_GROUP, REMEMBERED_TAB_KEY, "");
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.BANKMAIN)
		{
			slots = null;
			createButton();
		}
	}

	@Subscribe(priority = AFTER_LAYOUT_PLUGINS)
	public void onScriptPreFired(ScriptPreFired event)
	{
		if (event.getScriptId() != ScriptID.BANKMAIN_FINISHBUILDING || !isOpen())
		{
			return;
		}

		// The bank has decided which items are shown, but not yet how far it scrolls
		if (slots == null)
		{
			arrange();
		}

		int lastSlot = slots.values().stream().max(Integer::compare).orElse(0);
		// The script's arguments are still on the stack; the ninth from the end is the scroll height
		client.getIntStack()[client.getIntStackSize() - 9] = (lastSlot / BankTagsPlugin.BANK_ITEMS_PER_ROW + 1) * ROW_HEIGHT;
	}

	@Subscribe(priority = AFTER_LAYOUT_PLUGINS)
	public void onScriptPostFired(ScriptPostFired event)
	{
		// The bank is fully built, and any layout plugin has placed the items its way
		if (event.getScriptId() != ScriptID.BANKMAIN_BUILD)
		{
			return;
		}

		if (openRequested)
		{
			// Not from inside a script, which can't start another
			openRequested = false;
			clientThread.invokeLater(this::open);
		}

		if (isOpen())
		{
			if (slots == null)
			{
				arrange();
			}
			placeItems();
		}
		drawHeadings();
		updateButton();
	}

	/**
	 * Works out where each item the filter shows goes.
	 */
	private void arrange()
	{
		Set<Integer> shown = new LinkedHashSet<>();
		for (Widget widget : shownItems())
		{
			shown.add(itemManager.canonicalize(widget.getItemId()));
		}

		// The items shown only because the player listed them get a section of their own
		List<Integer> listed = new ArrayList<>();
		for (int itemId : shown)
		{
			if (spec.sectionOf(itemId) == null)
			{
				listed.add(itemId);
			}
		}
		BankFilterSpec.Arrangement arrangement = spec.with(BankSection.ALWAYS_SHOWN, listed).arrange(shown);
		Map<Integer, Integer> arranged = new HashMap<>();
		int[] layout = arrangement.getSlots();
		for (int slot = 0; slot < layout.length; slot++)
		{
			if (layout[slot] != -1)
			{
				arranged.put(layout[slot], slot);
			}
		}
		slots = arranged;
		headingRows = arrangement.getHeadingRows();
	}

	private void placeItems()
	{
		int nextFree = slots.values().stream().max(Integer::compare).orElse(-1) + 1;
		for (Widget widget : shownItems())
		{
			int itemId = itemManager.canonicalize(widget.getItemId());
			Integer slot = slots.get(itemId);
			if (slot == null)
			{
				// Deposited since the filter was arranged: keep it at the end, where it stays
				slot = nextFree++;
				slots.put(itemId, slot);
			}

			widget.setOriginalX((slot % BankTagsPlugin.BANK_ITEMS_PER_ROW) * COLUMN_WIDTH + BankTagsPlugin.BANK_ITEM_START_X);
			widget.setOriginalY((slot / BankTagsPlugin.BANK_ITEMS_PER_ROW) * ROW_HEIGHT);
			widget.revalidate();
		}
	}

	/**
	 * The item widgets the bank shows right now.
	 */
	private List<Widget> shownItems()
	{
		List<Widget> shown = new ArrayList<>();
		Widget container = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (container == null || container.getDynamicChildren() == null)
		{
			return shown;
		}

		for (Widget widget : container.getDynamicChildren())
		{
			// The game fills empty slots with a blank item
			if (!widget.isHidden() && widget.getItemId() >= 0 && widget.getItemId() != ItemID.BLANKOBJECT)
			{
				shown.add(widget);
			}
		}
		return shown;
	}

	private void toggle(ScriptEvent event)
	{
		if (event.getOp() != 2)
		{
			return;
		}

		if (isOpen())
		{
			close();
		}
		else
		{
			open();
		}
		client.playSoundEffect(SoundEffectID.INTERFACE_SELECT1);
	}

	private boolean shows(int itemId)
	{
		return sectionOf(itemManager.canonicalize(itemId)) != null;
	}

	/**
	 * The section an item goes in: the run's, unless the player has hidden it, or their own list's.
	 */
	@Nullable
	private BankSection sectionOf(int itemId)
	{
		Supplier<String> name = () -> itemManager.getItemComposition(itemId).getName();
		if (neverShown.contains(itemId, name))
		{
			return null;
		}
		BankSection section = spec.sectionOf(itemId);
		if (section == null && alwaysShown.contains(itemId, name))
		{
			return BankSection.ALWAYS_SHOWN;
		}
		return section;
	}

	private void createButton()
	{
		Widget parent = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
		if (parent == null)
		{
			return;
		}

		buttonBackground = parent.createChild(-1, WidgetType.GRAPHIC);
		buttonBackground.setOriginalX(BUTTON_X);
		buttonBackground.setOriginalY(BUTTON_Y);
		buttonBackground.setOriginalWidth(BUTTON_SIZE);
		buttonBackground.setOriginalHeight(BUTTON_SIZE);
		buttonBackground.setSpriteId(SpriteID.Miscgraphics3.UNKNOWN_BUTTON_SQUARE_SMALL);
		buttonBackground.setAction(1, BUTTON_ACTION);
		buttonBackground.setName("");
		buttonBackground.setHasListener(true);
		buttonBackground.setOnOpListener((JavaScriptCallback) this::toggle);
		buttonBackground.revalidate();

		buttonIcon = parent.createChild(-1, WidgetType.GRAPHIC);
		buttonIcon.setOriginalX(BUTTON_X + 3);
		buttonIcon.setOriginalY(BUTTON_Y + 3);
		buttonIcon.setOriginalWidth(BUTTON_SIZE - 6);
		buttonIcon.setOriginalHeight(BUTTON_SIZE - 6);
		buttonIcon.setSpriteId(SpriteID.Staticons2.FARMING);
		buttonIcon.revalidate();

		updateButton();
	}

	private void updateButton()
	{
		if (buttonBackground == null || buttonIcon == null)
		{
			return;
		}

		boolean available = isAvailable();
		buttonBackground.setHidden(!available);
		buttonIcon.setHidden(!available);
		buttonBackground.setSpriteId(isOpen()
			? SpriteID.Miscgraphics3.UNKNOWN_BUTTON_SQUARE_SMALL_SELECTED
			: SpriteID.Miscgraphics3.UNKNOWN_BUTTON_SQUARE_SMALL);
	}

	private void drawHeadings()
	{
		Widget container = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (container == null)
		{
			headingWidgets.clear();
			return;
		}

		// Widgets from before the bank was last closed are gone from the container
		headingWidgets.removeIf(widget -> container.getChild(widget.getIndex()) != widget);

		int used = 0;
		if (isOpen() && slots != null)
		{
			for (Map.Entry<BankSection, Integer> heading : headingRows.entrySet())
			{
				if (used == headingWidgets.size())
				{
					Widget created = container.createChild(-1, WidgetType.TEXT);
					created.setFontId(FontID.PLAIN_11);
					created.setTextColor(HEADING_COLOR);
					created.setTextShadowed(true);
					created.setOriginalX(BankTagsPlugin.BANK_ITEM_START_X);
					created.setOriginalWidth(ROW_WIDTH);
					created.setOriginalHeight(HEADING_HEIGHT);
					headingWidgets.add(created);
				}

				Widget widget = headingWidgets.get(used++);
				widget.setText(heading.getKey().getTitle());
				// At the foot of the empty row, just above the section's items
				widget.setOriginalY(heading.getValue() * ROW_HEIGHT + ROW_HEIGHT - HEADING_HEIGHT - 2);
				widget.setHidden(false);
				widget.revalidate();
			}
		}

		for (int i = used; i < headingWidgets.size(); i++)
		{
			headingWidgets.get(i).setHidden(true);
		}
	}

	@Nullable
	private BankTagsPlugin bankTagsPlugin()
	{
		for (Plugin plugin : pluginManager.getPlugins())
		{
			if (plugin instanceof BankTagsPlugin)
			{
				return pluginManager.isPluginActive(plugin) ? (BankTagsPlugin) plugin : null;
			}
		}
		return null;
	}
}

package com.plugandplant;

import java.util.ArrayList;
import java.util.Collection;
import java.util.EnumMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.annotation.Nullable;
import lombok.Value;

/**
 * Which items the bank filter shows, section by section.
 */
@Value
class BankFilterSpec
{
	static final BankFilterSpec EMPTY = new BankFilterSpec(Map.of());
	static final int ITEMS_PER_ROW = 8;

	/**
	 * The items of each section, in the order they are shown. An item is in the first section that has it.
	 */
	Map<BankSection, List<Integer>> sections;

	/**
	 * @param itemId a canonical item id: not a note or placeholder
	 * @return the section the item belongs in, or null if the filter doesn't show it
	 */
	@Nullable
	BankSection sectionOf(int itemId)
	{
		for (BankSection section : BankSection.values())
		{
			List<Integer> items = sections.get(section);
			if (items != null && items.contains(itemId))
			{
				return section;
			}
		}
		return null;
	}

	/**
	 * Where a section's items go in the layout, and which row its heading sits in.
	 */
	@Value
	static class Arrangement
	{
		/**
		 * Item id per bank slot, eight slots to a row; -1 for an empty slot.
		 */
		int[] slots;
		/**
		 * The row left empty above each section, for its heading.
		 */
		Map<BankSection, Integer> headingRows;
	}

	/**
	 * This spec with a section's items replaced.
	 */
	BankFilterSpec with(BankSection section, List<Integer> items)
	{
		Map<BankSection, List<Integer>> changed = new EnumMap<>(BankSection.class);
		changed.putAll(sections);
		changed.put(section, List.copyOf(items));
		return new BankFilterSpec(changed);
	}

	/**
	 * Lays the given items out section by section, each under an empty row for its heading.
	 *
	 * @param bankItemIds canonical ids of the items in the bank
	 */
	Arrangement arrange(Collection<Integer> bankItemIds)
	{
		Set<Integer> inBank = new LinkedHashSet<>(bankItemIds);
		List<Integer> slots = new ArrayList<>();
		Map<BankSection, Integer> headingRows = new EnumMap<>(BankSection.class);
		for (BankSection section : BankSection.values())
		{
			// The declared order, so related items sit together whatever order the bank is in
			List<Integer> items = new ArrayList<>();
			for (int itemId : sections.getOrDefault(section, List.of()))
			{
				if (inBank.contains(itemId) && sectionOf(itemId) == section && !items.contains(itemId))
				{
					items.add(itemId);
				}
			}
			if (items.isEmpty())
			{
				continue;
			}

			headingRows.put(section, slots.size() / ITEMS_PER_ROW);
			for (int i = 0; i < ITEMS_PER_ROW; i++)
			{
				slots.add(-1);
			}

			slots.addAll(items);
			while (slots.size() % ITEMS_PER_ROW != 0)
			{
				slots.add(-1);
			}
		}

		return new Arrangement(slots.stream().mapToInt(Integer::intValue).toArray(), headingRows);
	}
}

package com.plugandplant;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * The groups the bank filter lays items out in, in the order they are shown.
 */
@Getter
@RequiredArgsConstructor
enum BankSection
{
	/**
	 * Whatever the run uses that can be worn, first so it can all be taken and put on before the rest.
	 */
	WEARABLES("Wear"),
	EQUIPMENT("Equipment"),
	HERB_SEEDS("Herb seeds"),
	ALLOTMENT_SEEDS("Allotment seeds"),
	FLOWER_SEEDS("Flower seeds"),
	TREE_SAPLINGS("Tree saplings"),
	FRUIT_TREE_SAPLINGS("Fruit tree saplings"),
	/**
	 * Saplings for the special tree patches: hardwood, calquat, spirit, celastrus, redwood and crystal.
	 */
	SPECIAL_SAPLINGS("Special tree saplings"),
	PAYMENTS("Gardener payments"),
	TELEPORTS("Teleports"),
	/**
	 * Items the player has listed to always be shown, which the filter wouldn't show otherwise.
	 */
	ALWAYS_SHOWN("Always shown"),
	/**
	 * Tree seeds on their way to becoming saplings, and what it takes to grow them.
	 */
	GROWING("Saplings to grow");

	private final String title;
}

package com.plugandplant;

import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Tile;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.NpcSpawned;
import net.runelite.client.eventbus.Subscribe;

/**
 * Keeps track of the banks in the scene, booths, chests and bankers, to tell when the player is at
 * one and the "what to bring" checklist is worth showing.
 */
@Singleton
class Banks
{
	/**
	 * How close to a bank the player has to be to count as at it.
	 */
	private static final int RANGE = 12;

	private final Client client;
	private final Map<Object, WorldPoint> banks = new HashMap<>();

	@Inject
	Banks(Client client)
	{
		this.client = client;
	}

	boolean isNear(WorldPoint point)
	{
		for (WorldPoint bank : banks.values())
		{
			if (bank.getPlane() == point.getPlane() && bank.distanceTo2D(point) <= RANGE)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Finds the banks already in the scene. Only needed when tracking starts while logged in, as
	 * spawn events cover everything after that.
	 */
	void scan()
	{
		banks.clear();
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		WorldView worldView = client.getTopLevelWorldView();
		for (Tile[] row : worldView.getScene().getTiles()[worldView.getPlane()])
		{
			for (Tile tile : row)
			{
				if (tile == null)
				{
					continue;
				}
				for (GameObject object : tile.getGameObjects())
				{
					if (object != null)
					{
						add(object);
					}
				}
			}
		}
		for (NPC npc : worldView.npcs())
		{
			add(npc);
		}
	}

	void clear()
	{
		banks.clear();
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		add(event.getGameObject());
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		banks.remove(event.getGameObject());
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		add(event.getNpc());
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		banks.remove(event.getNpc());
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		// Objects spawn again once the map has loaded; bankers still in view don't, so they are kept
		switch (event.getGameState())
		{
			case LOADING:
				banks.keySet().removeIf(bank -> bank instanceof GameObject);
				break;
			case LOGGED_IN:
				break;
			default:
				banks.clear();
				break;
		}
	}

	private void add(GameObject object)
	{
		ObjectComposition composition = client.getObjectDefinition(object.getId());
		if (composition != null && composition.getImpostorIds() != null)
		{
			composition = composition.getImpostor();
		}
		if (composition != null && (offersBank(composition.getActions()) || isBankName(composition.getName())))
		{
			banks.put(object, Positions.of(client, object));
		}
	}

	private void add(NPC npc)
	{
		NPCComposition composition = npc.getTransformedComposition();
		if (composition != null && offersBank(composition.getActions()))
		{
			banks.put(npc, Positions.of(client, npc));
		}
	}

	private static boolean offersBank(String[] actions)
	{
		if (actions == null)
		{
			return false;
		}
		for (String action : actions)
		{
			if ("Bank".equals(action))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Bank chests often only offer "Use".
	 */
	private static boolean isBankName(String name)
	{
		return "Bank chest".equals(name) || "Bank booth".equals(name);
	}
}

package com.plugandplant;

import java.util.Collection;
import java.util.Map;
import java.util.Set;
import lombok.Value;

/**
 * A snapshot of what the player has on them, and of what they keep with the tool leprechaun.
 */
@Value
class Carried
{
	static final Carried NOTHING = new Carried(Map.of(), Map.of());

	/**
	 * Item id to quantity, over the inventory, worn equipment and a seed box whose contents are known.
	 */
	Map<Integer, Integer> items;
	/**
	 * Rune item id to quantity, for the runes in a carried rune pouch.
	 */
	Map<Integer, Integer> pouchRunes;
	/**
	 * Runes the equipped staff or tome supplies without end.
	 */
	Set<Integer> unlimitedRunes;
	/**
	 * Item id to quantity, for the tools and compost stored with the tool leprechaun.
	 */
	Map<Integer, Integer> stored;
	/**
	 * Whether the player carries a seed box the game hasn't shown the contents of.
	 */
	boolean seedBoxUnknown;
	/**
	 * Item id to quantity, for the inventory's items that aren't noted. {@link #items} counts noted
	 * items as the items themselves, so it can't tell.
	 */
	Map<Integer, Integer> unnoted;

	Carried(Map<Integer, Integer> items, Map<Integer, Integer> pouchRunes, Set<Integer> unlimitedRunes,
		Map<Integer, Integer> stored, boolean seedBoxUnknown, Map<Integer, Integer> unnoted)
	{
		this.items = items;
		this.pouchRunes = pouchRunes;
		this.unlimitedRunes = unlimitedRunes;
		this.stored = stored;
		this.seedBoxUnknown = seedBoxUnknown;
		this.unnoted = unnoted;
	}

	Carried(Map<Integer, Integer> items, Map<Integer, Integer> pouchRunes, Set<Integer> unlimitedRunes,
		Map<Integer, Integer> stored, boolean seedBoxUnknown)
	{
		this(items, pouchRunes, unlimitedRunes, stored, seedBoxUnknown, Map.of());
	}

	Carried(Map<Integer, Integer> items, Map<Integer, Integer> pouchRunes)
	{
		this(items, pouchRunes, Set.of(), Map.of(), false);
	}

	int count(int itemId)
	{
		return items.getOrDefault(itemId, 0);
	}

	int count(Collection<Integer> itemIds)
	{
		int total = 0;
		for (int itemId : itemIds)
		{
			total += count(itemId);
		}
		return total;
	}

	boolean has(int itemId)
	{
		return count(itemId) > 0;
	}

	boolean hasAny(Collection<Integer> itemIds)
	{
		return count(itemIds) > 0;
	}

	/**
	 * How many of the items the inventory holds unnoted.
	 */
	int unnoted(Collection<Integer> itemIds)
	{
		int total = 0;
		for (int itemId : itemIds)
		{
			total += unnoted.getOrDefault(itemId, 0);
		}
		return total;
	}

	int stored(int itemId)
	{
		return stored.getOrDefault(itemId, 0);
	}

	int stored(Collection<Integer> itemIds)
	{
		int total = 0;
		for (int itemId : itemIds)
		{
			total += stored(itemId);
		}
		return total;
	}

	/**
	 * Whether the player can cast or use the teleport with what they carry. Runes are counted in the
	 * inventory and rune pouch, combination runes count towards both their elements, and an equipped
	 * staff or tome covers its elements.
	 */
	boolean has(Teleport teleport)
	{
		return has(teleport, false);
	}

	/**
	 * @param itemsOnly whether only the teleport's items count, not runes to cast it
	 */
	boolean has(Teleport teleport, boolean itemsOnly)
	{
		if (hasAny(teleport.getItemIds()))
		{
			return true;
		}
		if (itemsOnly || !teleport.isSpell())
		{
			return false;
		}

		for (Map.Entry<Integer, Integer> rune : teleport.getRunes().entrySet())
		{
			if (!unlimitedRunes.contains(rune.getKey()) && runes(rune.getKey()) < rune.getValue())
			{
				return false;
			}
		}
		return true;
	}

	/**
	 * The runes of a kind the player carries, combination runes that stand in for it included.
	 */
	private int runes(int rune)
	{
		int total = count(rune) + pouchRunes.getOrDefault(rune, 0);
		for (Map.Entry<Integer, Set<Integer>> combination : Runes.COMBINATIONS.entrySet())
		{
			if (combination.getValue().contains(rune))
			{
				total += count(combination.getKey()) + pouchRunes.getOrDefault(combination.getKey(), 0);
			}
		}
		return total;
	}
}

package com.plugandplant;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.annotation.Nullable;
import lombok.Value;
import net.runelite.api.gameval.ItemID;

/**
 * Builds the list of what to bring for the rest of a run, checked off against what the player carries.
 */
final class Checklist
{
	/**
	 * What a gardener charges to take down a grown tree.
	 */
	static final int REMOVAL_COINS = 200;

	/**
	 * The optional parts of the checklist.
	 */
	@Value
	static class Options
	{
		RunPreset preset;
		boolean compost;
		boolean protect;
		boolean volcanicAsh;
		/**
		 * Every graceful piece's item ids, one list per piece, or empty to leave graceful out.
		 */
		List<List<Integer>> gracefulPieces;
	}

	private Checklist()
	{
	}

	/**
	 * @param carried what the player has on them, with noted items counted as the items themselves
	 */
	static List<ChecklistItem> build(RunPlan plan, Map<FarmPatch, PatchState> states, Map<FarmLocation, LocationSettings> settings,
		Carried carried, Options options, @Nullable FarmingContract contract)
	{
		List<ChecklistItem> items = new ArrayList<>();
		boolean seedBox = carried.isSeedBoxUnknown();
		RunPreset preset = options.getPreset();
		boolean trees = preset.includesTrees();

		// The seeds of what the run visits for are counted against what the stops need
		for (PatchType type : RunPreset.TYPES)
		{
			if (preset.role(type) != PatchRole.VISIT)
			{
				continue;
			}
			int needed = plan.seedsNeeded(type);
			if (needed == 0)
			{
				continue;
			}

			int have = carried.count(type.getSeeds());
			if (have >= needed)
			{
				items.add(new ChecklistItem(type.getSeedLabel(), have + " / " + needed, ChecklistItem.State.GOOD));
			}
			else if (seedBox && !type.isTree())
			{
				// A seed box's contents can't be read
				items.add(new ChecklistItem(type.getSeedLabel(), have + " / " + needed + " + box", ChecklistItem.State.UNSURE));
			}
			else
			{
				items.add(new ChecklistItem(type.getSeedLabel(), have + " / " + needed, ChecklistItem.State.MISSING));
			}
		}

		// What is tended while there takes whatever seeds the player brings, so these show how far they go
		for (PatchType type : RunPreset.TYPES)
		{
			if (preset.role(type) == PatchRole.TEND)
			{
				items.add(seedsFor(type, type.getSeedLabel(), carried, seedBox));
			}
		}

		if (contract != null)
		{
			boolean planting = plan.getContractSeeds().keySet().stream().anyMatch(plan.getToPlant()::contains);
			if (planting)
			{
				String label = "Contract: " + contract.seedLabel();
				int needed = contract.getType().getSeedsPerPatch();
				if (carried.count(contract.getSeed()) >= needed)
				{
					items.add(new ChecklistItem(label, "Yes", ChecklistItem.State.GOOD));
				}
				else
				{
					boolean unsure = seedBox && !contract.getType().isTree();
					items.add(new ChecklistItem(label, unsure ? "Check seed box" : "Missing",
						unsure ? ChecklistItem.State.UNSURE : ChecklistItem.State.MISSING));
				}
			}
		}

		if (trees && options.isProtect())
		{
			items.addAll(payments(plan, states, carried));
		}

		if (trees)
		{
			// A grown tree is taken down by its gardener for coins, or chopped, which needs an axe instead
			int removals = 0;
			for (Map.Entry<FarmPatch, Step> step : plan.getSteps().entrySet())
			{
				boolean removal = step.getValue() == Step.CHECK_HEALTH || step.getValue() == Step.REMOVE;
				if (removal && step.getKey().getType().isRemovedForCoins())
				{
					removals++;
				}
			}
			if (removals > 0)
			{
				int needed = removals * REMOVAL_COINS;
				int coins = carried.count(ItemID.COINS);
				if (coins >= needed)
				{
					items.add(new ChecklistItem("Coins", coins + " / " + needed, ChecklistItem.State.GOOD));
				}
				else if (carried.hasAny(RunItems.AXES))
				{
					items.add(new ChecklistItem("Coins", coins + " / " + needed + ", axe", ChecklistItem.State.GOOD));
				}
				else
				{
					items.add(new ChecklistItem("Coins", coins + " / " + needed + " or axe", ChecklistItem.State.MISSING));
				}
			}
		}

		if (options.isCompost())
		{
			int needed = plan.getToCompost().size();
			int buckets = carried.count(RunItems.COMPOST_BUCKETS);
			int storedBuckets = carried.stored(RunItems.COMPOST_BUCKETS);
			if (carried.has(ItemID.BOTTOMLESS_COMPOST_BUCKET_FILLED))
			{
				items.add(new ChecklistItem("Compost", "Bottomless", ChecklistItem.State.GOOD));
			}
			else if (buckets >= needed && (needed > 0 || buckets > 0))
			{
				items.add(new ChecklistItem("Compost", buckets + " / " + needed, ChecklistItem.State.GOOD));
			}
			else if (needed > 0 && carried.stored(ItemID.BOTTOMLESS_COMPOST_BUCKET_FILLED) > 0)
			{
				items.add(new ChecklistItem("Compost", "Bottomless at leprechaun", ChecklistItem.State.STORED));
			}
			else if (needed > 0 && buckets + storedBuckets >= needed)
			{
				items.add(new ChecklistItem("Compost", buckets + " / " + needed + ", " + storedBuckets + " at leprechaun",
					ChecklistItem.State.STORED));
			}
			else if (needed > 0)
			{
				// The player asked to compost, so coming up short is worth a red line
				items.add(new ChecklistItem("Compost", buckets + " / " + needed, ChecklistItem.State.MISSING));
			}
		}

		// Tools may be with the tool leprechaun, so one that isn't carried is unsure rather than missing
		items.add(tool("Spade", carried, List.of(ItemID.SPADE), true));
		boolean seedPatches = preset.includesSeedPatches();
		if (seedPatches)
		{
			items.add(tool("Seed dibber", carried, List.of(ItemID.DIBBER), true));
		}
		if (plan.has(Step.RAKE))
		{
			items.add(tool("Rake", carried, List.of(ItemID.RAKE), true));
		}
		// Trees are pruned rather than cured
		if (plan.getSteps().entrySet().stream().anyMatch(step -> step.getValue() == Step.CURE && step.getKey().getType().isTree()))
		{
			items.add(tool("Secateurs", carried, List.of(ItemID.SECATEURS, ItemID.FAIRY_ENCHANTED_SECATEURS), true));
		}
		if (plan.getSteps().entrySet().stream().anyMatch(step -> step.getValue() == Step.CURE && !step.getKey().getType().isTree()))
		{
			items.add(tool("Plant cure", carried, List.of(ItemID.PLANT_CURE), true));
		}
		// Celastrus bark and crystal shards are cut from the tree
		boolean chopping = plan.getSteps().entrySet().stream().anyMatch(step ->
			(step.getValue() == Step.CHECK_HEALTH || step.getValue() == Step.HARVEST)
				&& step.getKey().getType().harvestItems() == RunItems.AXES);
		if (chopping)
		{
			items.add(tool("Axe", carried, RunItems.AXES, true));
		}
		if (seedPatches)
		{
			// Only a bonus to the yield, so going without isn't missing anything
			items.add(tool("Magic secateurs", carried, List.of(ItemID.FAIRY_ENCHANTED_SECATEURS), false));
		}

		for (FarmLocation location : plan.targets())
		{
			Teleport choice = settings.getOrDefault(location, LocationSettings.DEFAULT).getTeleport();
			List<Teleport> teleports = location.teleportsFor(choice);
			if (teleports.isEmpty())
			{
				continue;
			}

			boolean particular = teleports.size() == 1 && teleports.get(0) == choice;
			boolean itemsOnly = location.itemsOnly(choice);
			String label = particular
				? location.getDisplayName() + ": " + choice.getLabel()
				: location.getDisplayName() + " teleport";
			if (teleports.stream().anyMatch(teleport -> carried.has(teleport, itemsOnly)))
			{
				items.add(new ChecklistItem(label, "Yes", ChecklistItem.State.GOOD));
			}
			else if (particular && !choice.isSpell() && !choice.isOptional())
			{
				items.add(new ChecklistItem(label, "Missing", ChecklistItem.State.MISSING));
			}
			else
			{
				// Runes may come from a staff, a fairy ring may not need one, and with no particular teleport
				// picked there may be another way there
				String value = choice.isOptional() ? "No staff" : choice.isSpell() ? "Not found" : "None";
				items.add(new ChecklistItem(label, value, ChecklistItem.State.UNSURE));
			}
		}

		if (!options.getGracefulPieces().isEmpty())
		{
			int pieces = 0;
			for (List<Integer> piece : options.getGracefulPieces())
			{
				if (carried.hasAny(piece))
				{
					pieces++;
				}
			}
			int all = options.getGracefulPieces().size();
			items.add(new ChecklistItem("Graceful", pieces + " / " + all,
				pieces == all ? ChecklistItem.State.GOOD : ChecklistItem.State.MISSING));
		}

		if (options.isVolcanicAsh())
		{
			int ash = carried.count(ItemID.FOSSIL_VOLCANIC_ASH);
			items.add(new ChecklistItem("Volcanic ash", ash > 0 ? Integer.toString(ash) : "None",
				ash > 0 ? ChecklistItem.State.GOOD : ChecklistItem.State.MISSING));
		}

		return items;
	}

	/**
	 * What protecting the trees will cost: every sapling the player brings is a tree they mean to
	 * plant and protect, and a tree planted on this run but not paid for yet still needs its payment.
	 * Saplings that share a payment are added together.
	 */
	private static List<ChecklistItem> payments(RunPlan plan, Map<FarmPatch, PatchState> states, Carried carried)
	{
		Map<Integer, Integer> needed = new LinkedHashMap<>();
		Map<Integer, String> names = new LinkedHashMap<>();
		for (Sapling sapling : Sapling.values())
		{
			int saplings = carried.count(sapling.getSapling()) + carried.count(sapling.getWateredSeedling());
			if (saplings > 0)
			{
				add(needed, names, sapling, saplings);
			}
		}

		int withoutSapling = 0;
		for (FarmPatch patch : plan.getToPay())
		{
			if (plan.getToPlant().contains(patch))
			{
				// Still to plant: paid for above if its sapling is carried
				if (!plan.getSeedsFor().containsKey(patch))
				{
					withoutSapling++;
				}
				continue;
			}

			Sapling tree = states.getOrDefault(patch, PatchState.UNKNOWN).getCrop();
			if (tree != null)
			{
				add(needed, names, tree, 1);
			}
		}

		List<ChecklistItem> items = new ArrayList<>();
		for (Map.Entry<Integer, Integer> payment : needed.entrySet())
		{
			int have = carried.count(payment.getKey());
			String name = names.get(payment.getKey());
			items.add(new ChecklistItem("Pay: " + name, have + " / " + payment.getValue(),
				have >= payment.getValue() ? ChecklistItem.State.GOOD : ChecklistItem.State.MISSING));
		}
		if (withoutSapling > 0)
		{
			// The payment depends on the tree, which isn't known until the player brings its sapling
			items.add(new ChecklistItem("Pay: for " + withoutSapling + (withoutSapling == 1 ? " more tree" : " more trees"),
				"Bring saplings", ChecklistItem.State.UNSURE));
		}
		return items;
	}

	private static void add(Map<Integer, Integer> needed, Map<Integer, String> names, Sapling tree, int trees)
	{
		for (Sapling.Payment payment : tree.getPayments())
		{
			needed.merge(payment.getItem(), trees * payment.getAmount(), Integer::sum);
			names.putIfAbsent(payment.getItem(), payment.getName());
		}
	}

	/**
	 * How many patches of a kind the carried seeds would plant. A patch takes several seeds of one kind.
	 */
	static int patchesPlantable(PatchType type, Carried carried)
	{
		int patches = 0;
		for (int seed : type.getSeeds())
		{
			patches += carried.count(seed) / type.getSeedsPerPatch();
		}
		return patches;
	}

	private static ChecklistItem seedsFor(PatchType type, String label, Carried carried, boolean seedBox)
	{
		int patches = patchesPlantable(type, carried);
		if (patches > 0)
		{
			return new ChecklistItem(label, patches == 1 ? "1 patch" : patches + " patches", ChecklistItem.State.GOOD);
		}
		return new ChecklistItem(label, seedBox ? "Seed box" : "None", ChecklistItem.State.UNSURE);
	}

	/**
	 * A tool, carried, kept with the tool leprechaun, or neither.
	 *
	 * @param needed whether the run can't do without it
	 */
	private static ChecklistItem tool(String label, Carried carried, List<Integer> itemIds, boolean needed)
	{
		if (carried.hasAny(itemIds))
		{
			return new ChecklistItem(label, "Yes", ChecklistItem.State.GOOD);
		}
		if (carried.stored(itemIds) > 0)
		{
			return new ChecklistItem(label, "At leprechaun", ChecklistItem.State.STORED);
		}
		return new ChecklistItem(label, "Not carried", needed ? ChecklistItem.State.MISSING : ChecklistItem.State.UNSURE);
	}

	/**
	 * House teleports are labelled "House: tab" for the dropdown; next to a location name "House tab" reads better.
	 */
}

package com.plugandplant;

import lombok.Value;

/**
 * One line of the "what to bring" checklist.
 */
@Value
class ChecklistItem
{
	enum State
	{
		GOOD,
		MISSING,
		/**
		 * Not on the player, but kept with the tool leprechaun, so it can be taken from there or the bank.
		 */
		STORED,
		/**
		 * Not found on the player, but they may well have it covered some way this plugin can't see,
		 * such as a seed box it hasn't been shown into, or an axe instead of coins.
		 */
		UNSURE
	}

	String label;
	String value;
	State state;
}

package com.plugandplant;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.List;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * An in-game box with the steps at the location the player is at and the checklist of what to bring.
 */
@Singleton
class ChecklistOverlay extends OverlayPanel
{
	private static final int WIDTH = 190;
	/**
	 * For items kept with the tool leprechaun: not on the player, but not missing either.
	 */
	static final Color STORED_COLOR = new Color(0x6C, 0xB4, 0xEE);

	@Value
	static class Line
	{
		String left;
		String right;
		Color rightColor;
	}

	@Value
	static class Content
	{
		String title;
		/**
		 * The patches at the location the player is at, with the next step at each; empty elsewhere.
		 */
		List<Line> steps;
		List<Line> checklist;
	}

	/**
	 * Null while the overlay is hidden.
	 */
	@Nullable
	private Content content;

	@Inject
	ChecklistOverlay()
	{
		setPosition(OverlayPosition.TOP_LEFT);
		panelComponent.setPreferredSize(new Dimension(WIDTH, 0));
	}

	void setContent(@Nullable Content content)
	{
		this.content = content;
	}

	static Color color(ChecklistItem.State state)
	{
		switch (state)
		{
			case GOOD:
				return ColorScheme.PROGRESS_COMPLETE_COLOR;
			case MISSING:
				return ColorScheme.PROGRESS_ERROR_COLOR;
			case STORED:
				return STORED_COLOR;
			default:
				return ColorScheme.LIGHT_GRAY_COLOR;
		}
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Content shown = content;
		if (shown == null)
		{
			return null;
		}

		panelComponent.getChildren().add(TitleComponent.builder().text(shown.getTitle()).build());
		for (Line line : shown.getSteps())
		{
			add(line);
		}
		if (!shown.getSteps().isEmpty() && !shown.getChecklist().isEmpty())
		{
			panelComponent.getChildren().add(LineComponent.builder().build());
		}
		for (Line line : shown.getChecklist())
		{
			add(line);
		}
		return super.render(graphics);
	}

	private void add(Line line)
	{
		panelComponent.getChildren().add(LineComponent.builder()
			.left(line.getLeft())
			.right(line.getRight())
			.rightColor(line.getRightColor())
			.build());
	}
}

package com.plugandplant;

import java.util.ArrayList;
import java.util.List;
import javax.annotation.Nullable;
import lombok.Getter;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.NpcID;
import net.runelite.api.gameval.VarbitID;

/**
 * The farming locations runs stop at: those with a herb patch, each with the allotments and flower
 * patch beside it, and those with tree patches of any kind. Regions and varbits are the ones the
 * Time Tracking plugin files each patch under.
 */
@Getter
public enum FarmLocation
{
	FALADOR("Falador", 20,
		new Patches(12083).herb(VarbitID.FARMING_TRANSMIT_D, new WorldPoint(3058, 3311, 0))
			.allotment("North-west allotment", VarbitID.FARMING_TRANSMIT_A)
			.allotment("South-east allotment", VarbitID.FARMING_TRANSMIT_B)
			.flower(VarbitID.FARMING_TRANSMIT_C),
		Teleport.EXPLORERS_RING, Teleport.FALADOR_TELEPORT, Teleport.DRAYNOR_MANOR_TELEPORT, Teleport.RING_OF_WEALTH,
		Teleport.SKILLS_NECKLACE, Teleport.AMULET_OF_GLORY, Teleport.RING_OF_THE_ELEMENTS),
	CATHERBY("Catherby", 20,
		new Patches(11062).herb(VarbitID.FARMING_TRANSMIT_D, new WorldPoint(2813, 3463, 0))
