package com.plugandplant;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.NpcChanged;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.NpcSpawned;
import net.runelite.client.eventbus.Subscribe;

/**
 * Keeps track of the gardeners in the scene who look after tree patches, so they can be highlighted
 * when it is time to pay them, and of the tool leprechauns by herb patches, for noting herbs.
 *
 * A gardener is recognised by the NPC id Time Tracking knows them by, or else as an NPC offering to
 * be paid right beside a tree patch: some gardeners change ids with quests and game updates.
 */
@Singleton
class Gardeners
{
	/**
	 * How far from their tree a gardener without a known id may stand and still be taken for its gardener.
	 */
	private static final int GARDENER_RANGE = 12;

	private static final String TOOL_LEPRECHAUN = "Tool Leprechaun";

	private final Client client;
	private final Map<NPC, FarmPatch> gardeners = new HashMap<>();
	private final Map<NPC, FarmLocation> leprechauns = new HashMap<>();

	@Inject
	Gardeners(Client client)
	{
		this.client = client;
	}

	/**
	 * The gardeners in the scene, with the patch each looks after.
	 */
	Map<NPC, FarmPatch> get()
	{
		return Collections.unmodifiableMap(gardeners);
	}

	/**
	 * The tool leprechauns in the scene that stand at a location with a herb patch.
	 */
	Map<NPC, FarmLocation> leprechauns()
	{
		return Collections.unmodifiableMap(leprechauns);
	}

	/**
	 * Finds the gardeners already in the scene. Only needed when tracking starts while logged in, as
	 * spawn events cover everything after that.
	 */
	void scan()
	{
		gardeners.clear();
		leprechauns.clear();
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		for (NPC npc : client.getTopLevelWorldView().npcs())
		{
			update(npc);
		}
	}

	void clear()
	{
		gardeners.clear();
		leprechauns.clear();
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		update(event.getNpc());
	}

	@Subscribe
	public void onNpcChanged(NpcChanged event)
	{
		update(event.getNpc());
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		gardeners.remove(event.getNpc());
		leprechauns.remove(event.getNpc());
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		// Unlike objects, NPCs still in view aren't spawned again after the map loads a new area, so the
		// gardeners are kept through loading and checked again once it is done
		switch (event.getGameState())
		{
			case LOGGED_IN:
				scan();
				break;
			case LOADING:
				break;
			default:
				clear();
				break;
		}
	}

	private void update(NPC npc)
	{
		FarmPatch patch = patchOf(npc);
		if (patch != null)
		{
			gardeners.put(npc, patch);
		}
		else
		{
			gardeners.remove(npc);
		}

		FarmLocation location = TOOL_LEPRECHAUN.equals(npc.getName()) ? herbLocationOf(npc) : null;
		if (location != null)
		{
			leprechauns.put(npc, location);
		}
		else
		{
			leprechauns.remove(npc);
		}
	}

	@Nullable
	private FarmLocation herbLocationOf(NPC npc)
	{
		WorldPoint point = Positions.of(client, npc);
		for (FarmLocation location : FarmLocation.values())
		{
			if (location.hasToolLeprechaun() && location.isNear(point, 0))
			{
				return location;
			}
		}
		return null;
	}

	@Nullable
	private FarmPatch patchOf(NPC npc)
	{
		WorldPoint point = Positions.of(client, npc);
		FarmPatch nearest = null;
		for (FarmLocation location : FarmLocation.values())
		{
			if (!location.isNear(point, 0))
			{
				continue;
			}

			for (FarmPatch patch : location.getPatches())
			{
				if (!patch.getType().isTree() || point.getPlane() != patch.getPoint().getPlane())
				{
					continue;
				}
				if (patch.getGardener() == npc.getId())
				{
					return patch;
				}
				if (point.distanceTo2D(patch.getPoint()) <= GARDENER_RANGE
					&& (nearest == null || point.distanceTo2D(patch.getPoint()) < point.distanceTo2D(nearest.getPoint())))
				{
					nearest = patch;
				}
			}
		}
		return nearest != null && offersPayment(npc) ? nearest : null;
	}

	private static boolean offersPayment(NPC npc)
	{
		NPCComposition composition = npc.getTransformedComposition();
		if (composition == null)
		{
			composition = npc.getComposition();
		}
		if (composition == null || composition.getActions() == null)
		{
			return false;
		}

		for (String action : composition.getActions())
		{
			if (action != null && action.startsWith("Pay"))
			{
				return true;
			}
		}
		return false;
	}
}

package com.plugandplant;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

/**
 * Highlights the inventory items the patches the player is at need next, in the colour of the step:
 * seeds when a patch needs planting, compost when it needs compost, and so on. Run items that could
 * be worn in a free slot are highlighted too, to make room.
 */
@Singleton
class ItemHighlightOverlay extends WidgetItemOverlay
{
	private static final int FILL_ALPHA = 40;
	/**
	 * For run items that could be worn in a free slot to make room in the inventory.
	 */
	static final Color WEAR_COLOR = Color.WHITE;

	private final ItemManager itemManager;
	/**
	 * Canonical item id to highlight colour. Worked out by the plugin whenever the plan changes.
	 */
	private Map<Integer, Color> items = Map.of();
	/**
	 * Canonical ids among {@link #items} to highlight only when not noted: produce to take to the leprechaun.
	 */
	private Set<Integer> unnotedOnly = Set.of();

	@Inject
	ItemHighlightOverlay(ItemManager itemManager)
	{
		this.itemManager = itemManager;
		showOnInventory();
	}

	void setItems(Map<Integer, Color> items, Set<Integer> unnotedOnly)
	{
		this.items = items;
		this.unnotedOnly = unnotedOnly;
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		// Payments can be noted, but produce to note is only highlighted until it is
		int canonical = itemManager.canonicalize(itemId);
		Color color = items.get(canonical);
		if (color == null || (canonical != itemId && unnotedOnly.contains(canonical)))
		{
			return;
		}

		Rectangle bounds = widgetItem.getCanvasBounds();
		graphics.setColor(new Color(color.getRed(), color.getGreen(), color.getBlue(), FILL_ALPHA));
		graphics.fill(bounds);

		BufferedImage outline = itemManager.getItemOutline(itemId, widgetItem.getQuantity(), color);
		graphics.drawImage(outline, (int) bounds.getX(), (int) bounds.getY(), null);
	}
}

package com.plugandplant;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.function.Supplier;
import javax.annotation.Nullable;
import lombok.EqualsAndHashCode;
import net.runelite.client.util.WildcardMatcher;

/**
 * Items the player has listed in the settings, by name or item id, separated by commas or new lines.
 * Names ignore case, and * in one matches any text, so "Ring of dueling*" covers every charge.
 */
@EqualsAndHashCode
final class ItemList
{
	static final ItemList EMPTY = new ItemList(Set.of(), List.of());

	private final Set<Integer> ids;
	private final List<String> names;

	private ItemList(Set<Integer> ids, List<String> names)
	{
		this.ids = ids;
		this.names = names;
	}

	static ItemList parse(@Nullable String text)
	{
		if (text == null || text.isBlank())
		{
			return EMPTY;
		}

		Set<Integer> ids = new HashSet<>();
		List<String> names = new ArrayList<>();
		for (String entry : text.split("[,\\n]"))
		{
			String trimmed = entry.trim();
			if (trimmed.isEmpty())
			{
				continue;
			}
			if (trimmed.matches("\\d+"))
			{
				ids.add(Integer.parseInt(trimmed));
			}
			else
			{
				names.add(trimmed);
			}
		}
		return new ItemList(Set.copyOf(ids), List.copyOf(names));
	}

	boolean isEmpty()
	{
		return ids.isEmpty() && names.isEmpty();
	}

	/**
	 * @param name the item's name, looked up only when the list has names to compare it with
	 */
	boolean contains(int itemId, Supplier<String> name)
	{
		if (ids.contains(itemId))
		{
			return true;
		}
		if (names.isEmpty())
		{
			return false;
		}
		String itemName = name.get();
		if (itemName == null)
		{
			return false;
		}
		for (String pattern : names)
		{
			if (WildcardMatcher.matches(pattern, itemName))
			{
				return true;
			}
		}
		return false;
	}
}

