package com.plugandplant;

import javax.annotation.Nullable;

/**
 * Turns what the Time Tracking plugin last saw at a patch into its state now.
 *
 * Time Tracking stores each patch as "varbitValue:unixSeconds". The growth-tick maths is mirrored
 * from its FarmingTracker so both plugins agree on when a crop is done.
 */
final class PatchDecoder
{
	private PatchDecoder()
	{
	}

	/**
	 * @param stored              Time Tracking's stored value for the patch, or null if it has none
	 * @param now                 unix time in seconds
	 * @param offsetPrecisionMins Time Tracking's farmTickOffsetPrecision for the account, if known
	 * @param offsetMins          Time Tracking's farmTickOffset for the account, if known
	 */
	static PatchState predict(PatchType type, @Nullable String stored, long now,
		@Nullable Integer offsetPrecisionMins, @Nullable Integer offsetMins)
	{
		if (stored == null)
		{
			return PatchState.UNKNOWN;
		}

		String[] parts = stored.split(":");
		if (parts.length != 2)
		{
			return PatchState.UNKNOWN;
		}

		int value;
		long seenAt;
		try
		{
			value = Integer.parseInt(parts[0]);
			seenAt = Long.parseLong(parts[1]);
		}
		catch (NumberFormatException e)
		{
			return PatchState.UNKNOWN;
		}

		int[] table = type.getStateTable();
		if (seenAt <= 0 || value < 0 || value >= table.length)
		{
			return PatchState.UNKNOWN;
		}

		int code = table[value];
		Sapling crop = type.getCrops() == null ? null : type.getCrops()[value];
		if (code >= 0)
		{
			// A healthy crop with that many growth ticks to go, counted from the tick it was seen in
			int tick = type.getTickMinutes();
			long seenTick = tickTime(tick, 0, seenAt, offsetPrecisionMins, offsetMins);
			long readyAt = tickTime(tick, code, seenTick, offsetPrecisionMins, offsetMins);
			return readyAt <= now
				? new PatchState(type.grownStatus(), 0, crop)
				: new PatchState(PatchStatus.GROWING, readyAt, crop);
		}

		PatchStatus status = settledStatus(code);
		return new PatchState(status, 0, status == PatchStatus.WEEDS || status == PatchStatus.EMPTY ? null : crop);
	}

	private static PatchStatus settledStatus(int code)
	{
		switch (code)
		{
			case PatchStateTables.CLEAR:
				return PatchStatus.EMPTY;
			case PatchStateTables.WEEDS:
				return PatchStatus.WEEDS;
			case PatchStateTables.READY:
				return PatchStatus.READY;
			case PatchStateTables.DISEASED:
				return PatchStatus.DISEASED;
			case PatchStateTables.DEAD:
				return PatchStatus.DEAD;
			case PatchStateTables.CHECK_HEALTH:
				return PatchStatus.CHECK_HEALTH;
			case PatchStateTables.GROWN:
				return PatchStatus.GROWN;
			case PatchStateTables.STUMP:
				return PatchStatus.STUMP;
			default:
				return PatchStatus.UNKNOWN;
		}
	}

	/**
	 * The time of the growth tick {@code ticks} after the one containing {@code time}, in unix seconds.
	 */
	static long tickTime(int tickRateMins, int ticks, long time,
		@Nullable Integer offsetPrecisionMins, @Nullable Integer offsetMins)
	{
		// Offsets are negative but are stored as positive
		long offset = 0;
		if (offsetPrecisionMins != null && offsetMins != null
			&& (offsetPrecisionMins >= tickRateMins || offsetPrecisionMins >= 40))
		{
			offset = (offsetMins % tickRateMins) * 60L;
		}

		long shifted = time + offset;
		long tickSeconds = tickRateMins * 60L;
		long currentTick = shifted - (shifted % tickSeconds);
		return currentTick + ticks * tickSeconds - offset;
	}
}

package com.plugandplant;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Tile;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.eventbus.Subscribe;

/**
 * Keeps track of the patch objects in the scene, so they can be highlighted without searching for
 * them every frame.
 *
 * A patch is recognised by where it is and which varbit its object changes with, the same varbit
 * Time Tracking files it under, rather than by a list of object ids.
 */
@Slf4j
@Singleton
class PatchObjects
{
	private final Client client;
	private final Map<GameObject, FarmPatch> objects = new HashMap<>();

	@Inject
	PatchObjects(Client client)
	{
		this.client = client;
	}

	/**
	 * The patch objects in the scene. A patch can be made of more than one object.
	 */
	Map<GameObject, FarmPatch> get()
	{
		return Collections.unmodifiableMap(objects);
	}

	/**
	 * Finds the patches already in the scene. Only needed when tracking starts while logged in, as
	 * spawn events cover everything after that.
	 */
	void scan()
	{
		objects.clear();
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		WorldView worldView = client.getTopLevelWorldView();
		Tile[][] plane = worldView.getScene().getTiles()[worldView.getPlane()];
		for (Tile[] row : plane)
		{
			for (Tile tile : row)
			{
				if (tile == null)
				{
					continue;
				}
				for (GameObject object : tile.getGameObjects())
				{
					if (object != null)
					{
						add(object);
					}
				}
			}
		}
	}

	void clear()
	{
		objects.clear();
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		add(event.getGameObject());
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		objects.remove(event.getGameObject());
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		// The scene is rebuilt on loading, and its objects spawn again
		if (event.getGameState() != GameState.LOGGED_IN)
		{
			objects.clear();
		}
	}

	private void add(GameObject object)
	{
		FarmPatch patch = patchOf(object);
		if (patch != null)
		{
			log.debug("Found {} at {}", patch, Positions.of(client, object));
			objects.put(object, patch);
		}
	}

	@Nullable
	private FarmPatch patchOf(GameObject object)
	{
		WorldPoint point = Positions.of(client, object);
		for (FarmLocation location : FarmLocation.values())
		{
			if (!location.isNear(point, 0))
			{
				continue;
			}

			// Only now look the object up; nearly every object in the game is ruled out by the distance check
			ObjectComposition composition = client.getObjectDefinition(object.getId());
			if (composition == null || composition.getImpostorIds() == null)
			{
				return null;
			}

			// Patches at a location in different regions can share a varbit; the object is the nearest one's
			FarmPatch nearest = null;
			for (FarmPatch patch : location.getPatches())
			{
				if (patch.getVarbit() == composition.getVarbitId()
					&& (nearest == null || point.distanceTo2D(patch.getPoint()) < point.distanceTo2D(nearest.getPoint())))
				{
					nearest = patch;
				}
			}
			return nearest;
		}
		return null;
	}
}

package com.plugandplant;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Stroke;
import java.util.List;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.NPC;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

/**
 * Draws a box in the colour of its next step over each patch that has something to do, and labels
 * it. A gardener to pay gets one too.
 */
@Singleton
class PatchOverlay extends Overlay
{
	private static final Stroke BORDER = new BasicStroke(2);
	private static final int FILL_ALPHA = 50;
	private static final int LABEL_HEIGHT = 60;
	private static final int NPC_LABEL_OFFSET = 40;

	@Value
	static class Highlight
	{
		GameObject object;
		Color color;
		/**
		 * What to do, on one object of each patch; null on the patch's other objects.
		 */
		@Nullable
		String label;
	}

	/**
	 * A patch whose object hasn't been recognised in the scene, boxed on its known tile instead so
	 * there is always something to see.
	 */
	@Value
	static class TileHighlight
	{
		WorldPoint point;
		Color color;
		String label;
	}

	@Value
	static class NpcHighlight
	{
		NPC npc;
		Color color;
		String label;
	}

	private final Client client;
	/**
	 * Worked out by the plugin whenever the plan changes, so that drawing a frame is only drawing.
	 */
	private List<Highlight> highlights = List.of();
	private List<NpcHighlight> npcHighlights = List.of();
	private List<TileHighlight> tileHighlights = List.of();

	@Inject
	PatchOverlay(Client client)
	{
		this.client = client;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	void setHighlights(List<Highlight> highlights, List<NpcHighlight> npcHighlights, List<TileHighlight> tileHighlights)
	{
		this.highlights = highlights;
		this.npcHighlights = npcHighlights;
		this.tileHighlights = tileHighlights;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		for (Highlight highlight : highlights)
		{
			GameObject object = highlight.getObject();
			Color color = highlight.getColor();
			Polygon area = Perspective.getCanvasTileAreaPoly(client, object.getLocalLocation(),
				object.sizeX(), object.sizeY(), object.getPlane(), 0);
			if (area != null)
			{
				OverlayUtil.renderPolygon(graphics, area, color, fill(color), BORDER);
			}

			if (highlight.getLabel() != null)
			{
				Point location = object.getCanvasTextLocation(graphics, highlight.getLabel(), LABEL_HEIGHT);
				if (location != null)
				{
					OverlayUtil.renderTextLocation(graphics, location, highlight.getLabel(), color);
				}
			}
		}

		for (TileHighlight highlight : tileHighlights)
		{
			LocalPoint local = Positions.toScene(client, highlight.getPoint());
			if (local == null)
			{
				continue;
			}
			Color color = highlight.getColor();
			Polygon tile = Perspective.getCanvasTileAreaPoly(client, local, 2);
			if (tile != null)
			{
				OverlayUtil.renderPolygon(graphics, tile, color, fill(color), BORDER);
			}
			Point location = Perspective.getCanvasTextLocation(client, graphics, local, highlight.getLabel(), LABEL_HEIGHT);
			if (location != null)
			{
				OverlayUtil.renderTextLocation(graphics, location, highlight.getLabel(), color);
			}
		}

		for (NpcHighlight highlight : npcHighlights)
		{
			NPC npc = highlight.getNpc();
			// A gardener that has just left the scene can't be drawn
			if (npc.getComposition() == null || npc.getTransformedComposition() == null)
			{
				continue;
			}
			Color color = highlight.getColor();
			Polygon tile = npc.getCanvasTilePoly();
			if (tile != null)
			{
				OverlayUtil.renderPolygon(graphics, tile, color, fill(color), BORDER);
			}

			Point location = npc.getCanvasTextLocation(graphics, highlight.getLabel(), npc.getLogicalHeight() + NPC_LABEL_OFFSET);
			if (location != null)
			{
				OverlayUtil.renderTextLocation(graphics, location, highlight.getLabel(), color);
			}
		}
		return null;
	}

	private static Color fill(Color color)
	{
		return new Color(color.getRed(), color.getGreen(), color.getBlue(), FILL_ALPHA);
	}
}

package com.plugandplant;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * What a run does with a kind of patch.
 */
@Getter
@RequiredArgsConstructor
enum PatchRole
{
	OFF("Off"),
	/**
	 * Tended at the stops the run makes anyway, for as long as the player has seeds for it.
	 */
	TEND("Tend while there"),
	/**
	 * Makes a location a stop when it needs attention.
	 */
	VISIT("Visit for");

	private final String label;

	@Override
	public String toString()
	{
		return label;
	}
}

package com.plugandplant;

import javax.annotation.Nullable;
import lombok.Value;

@Value
public class PatchState
{
	static final PatchState UNKNOWN = new PatchState(PatchStatus.UNKNOWN, 0);

	PatchStatus status;
	/**
	 * Unix time in seconds the crop finishes growing; 0 unless the status is {@link PatchStatus#GROWING}.
	 */
	long readyAt;
	/**
	 * The tree in the patch, for tree patches with one in.
	 */
	@Nullable
	Sapling crop;

	PatchState(PatchStatus status, long readyAt, @Nullable Sapling crop)
	{
		this.status = status;
		this.readyAt = readyAt;
		this.crop = crop;
	}

	PatchState(PatchStatus status, long readyAt)
	{
		this(status, readyAt, null);
	}
}

package com.plugandplant;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

@RequiredArgsConstructor
public enum PatchStatus
{
	READY("Ready", true),
	/**
	 * A tree that has finished growing and waits for its health check.
	 */
	CHECK_HEALTH("Check health", true),
	/**
	 * A tree whose health has been checked, still standing.
	 */
	GROWN("Grown", true),
	STUMP("Stump", true),
	/**
	 * Weeds that have to be raked before anything can be planted.
	 */
	WEEDS("Weeds", true),
	/**
	 * Raked and ready to plant.
	 */
	EMPTY("Empty", true),
	DISEASED("Diseased", true),
	DEAD("Dead", true),
	GROWING("Growing", false),
	/**
	 * Time Tracking has never seen this patch on this account.
	 */
	UNKNOWN("No data", false);

	@Getter
	private final String label;
	private final boolean needsVisit;

	/**
	 * Whether a run should stop at a patch in this state.
	 */
	boolean needsVisit()
	{
		return needsVisit;
	}

	/**
	 * Whether whatever is in the patch makes way for a new crop: everything that needs a visit but
	 * a crop that only needs curing.
	 */
	boolean leadsToReplanting()
	{
		return needsVisit && this != DISEASED;
	}
}

package com.plugandplant;

import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

/**
 * Reads patch states out of the Time Tracking plugin's saved data for the logged in account.
 */
@Singleton
class PatchTracker
{
	static final String TIME_TRACKING_GROUP = "timetracking";
	private static final String FARM_TICK_OFFSET = "farmTickOffset";
	private static final String FARM_TICK_OFFSET_PRECISION = "farmTickOffsetPrecision";
	private static final String COMPOST_SUFFIX = ".compost";
	private static final String PROTECTED_SUFFIX = ".protected";

	private final ConfigManager configManager;

	@Inject
	PatchTracker(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	Map<FarmPatch, PatchState> readStates(long now)
	{
		Integer offsetPrecision = configManager.getRSProfileConfiguration(TIME_TRACKING_GROUP, FARM_TICK_OFFSET_PRECISION, int.class);
		Integer offset = configManager.getRSProfileConfiguration(TIME_TRACKING_GROUP, FARM_TICK_OFFSET, int.class);

		Map<FarmPatch, PatchState> states = new LinkedHashMap<>();
		for (FarmLocation location : FarmLocation.values())
		{
			for (FarmPatch patch : location.getPatches())
			{
				String stored = configManager.getRSProfileConfiguration(TIME_TRACKING_GROUP, patch.timeTrackingKey());
				states.put(patch, PatchDecoder.predict(patch.getType(), stored, now, offsetPrecision, offset));
			}
		}
		return states;
	}

	/**
	 * The patches Time Tracking has seen treated with compost. It notes this when the compost goes on
	 * and forgets it when the crop is harvested or dies.
	 */
	Set<FarmPatch> readComposted()
	{
		return readMarked(COMPOST_SUFFIX);
	}

	/**
	 * The trees Time Tracking has seen a gardener paid to protect. It notes this when the payment is
	 * made and forgets it when the tree is harvested or dies.
	 */
	Set<FarmPatch> readProtected()
	{
		return readMarked(PROTECTED_SUFFIX);
	}

	private Set<FarmPatch> readMarked(String suffix)
	{
		Set<FarmPatch> marked = new HashSet<>();
		for (FarmLocation location : FarmLocation.values())
		{
			for (FarmPatch patch : location.getPatches())
			{
				String value = configManager.getRSProfileConfiguration(TIME_TRACKING_GROUP, patch.timeTrackingKey() + suffix);
				if (value != null && !"false".equals(value))
				{
					marked.add(patch);
				}
			}
		}
		return marked;
	}
}

package com.plugandplant;

import java.util.List;
import java.util.Set;
import javax.annotation.Nullable;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.runelite.api.gameval.ItemID;

@Getter
@RequiredArgsConstructor
public enum PatchType
{
	HERB("Herbs", "Herb patch", "Herb seeds", 20, PatchStateTables.HERB, null, 1, RunItems.HERB_SEEDS, List.of(), 1),
	ALLOTMENT("Allotments", "Allotment", "Allotment seeds", 10, PatchStateTables.ALLOTMENT, null, 3, RunItems.ALLOTMENT_SEEDS,
		List.of(), 1),
	FLOWER("Flowers", "Flower patch", "Flower seeds", 5, PatchStateTables.FLOWER, null, 1, RunItems.FLOWER_SEEDS, List.of(), 1),
	TREE("Trees", "Tree patch", "Tree saplings", 40, PatchStateTables.TREE, PatchStateTables.TREE_CROPS, 1,
		RunItems.TREE_SAPLINGS, RunItems.TREE_SEEDS, 1),
	FRUIT_TREE("Fruit trees", "Fruit tree patch", "Fruit tree saplings", 160, PatchStateTables.FRUIT_TREE,
		PatchStateTables.FRUIT_TREE_CROPS, 1, RunItems.FRUIT_TREE_SAPLINGS, RunItems.FRUIT_TREE_SEEDS, 1),
	HARDWOOD_TREE("Hardwood trees", "Hardwood patch", "Hardwood saplings", 640, PatchStateTables.HARDWOOD_TREE,
		PatchStateTables.HARDWOOD_TREE_CROPS, 1, RunItems.HARDWOOD_SAPLINGS, RunItems.HARDWOOD_SEEDS, 35),
	CALQUAT("Calquats", "Calquat patch", "Calquat saplings", 160, PatchStateTables.CALQUAT, PatchStateTables.CALQUAT_CROPS,
		1, RunItems.CALQUAT_SAPLINGS, RunItems.CALQUAT_SEEDS, 72),
	SPIRIT_TREE("Spirit trees", "Spirit tree patch", "Spirit saplings", 320, PatchStateTables.SPIRIT_TREE,
		PatchStateTables.SPIRIT_TREE_CROPS, 1, RunItems.SPIRIT_SAPLINGS, RunItems.SPIRIT_SEEDS, 83),
	CELASTRUS("Celastrus", "Celastrus patch", "Celastrus saplings", 160, PatchStateTables.CELASTRUS,
		PatchStateTables.CELASTRUS_CROPS, 1, RunItems.CELASTRUS_SAPLINGS, RunItems.CELASTRUS_SEEDS, 85),
	REDWOOD("Redwoods", "Redwood patch", "Redwood saplings", 640, PatchStateTables.REDWOOD, PatchStateTables.REDWOOD_CROPS,
		1, RunItems.REDWOOD_SAPLINGS, RunItems.REDWOOD_SEEDS, 90),
	CRYSTAL_TREE("Crystal trees", "Crystal tree patch", "Crystal saplings", 80, PatchStateTables.CRYSTAL_TREE,
		PatchStateTables.CRYSTAL_TREE_CROPS, 1, RunItems.CRYSTAL_SAPLINGS, RunItems.CRYSTAL_SEEDS, 74);

	/**
	 * What the side panel calls patches of this kind, such as "Fruit trees".
	 */
	private final String pluralName;
	/**
	 * What a patch of this kind is called when it is the only one at its location.
	 */
	private final String patchName;
	private final String seedLabel;
	/**
	 * Minutes between growth ticks.
	 */
	private final int tickMinutes;
	/**
	 * What each varbit value means; see {@link PatchStateTables}.
	 */
	private final int[] stateTable;
	/**
	 * Which tree grows at each varbit value; null for patches that aren't trees.
	 */
	@Nullable
	private final Sapling[] crops;
	private final int seedsPerPatch;
	/**
	 * Any of these can be planted, so the player picks what to grow.
	 */
	private final List<Integer> seeds;
	/**
	 * The seeds and unwatered seedlings that grow into this kind's saplings.
	 */
	private final List<Integer> saplingSeeds;
	/**
	 * The Farming level it takes to plant anything here; 1 for kinds whose lowest crop is low enough
	 * not to matter.
	 */
	private final int plantLevel;

	boolean isTree()
	{
		return crops != null;
	}

	/**
	 * Whether the patch is one of the special tree patches, beyond trees and fruit trees.
	 */
	boolean isSpecialTree()
	{
		return isTree() && this != TREE && this != FRUIT_TREE;
	}

	/**
	 * Whether a gardener can be paid to protect what grows here; crystal trees can't get diseased.
	 */
	boolean isProtectable()
	{
		return isTree() && this != CRYSTAL_TREE;
	}

	/**
	 * What a crop is once it has finished growing: ready to harvest, or for a tree, waiting for its
	 * health check.
	 */
	PatchStatus grownStatus()
	{
		return isTree() ? PatchStatus.CHECK_HEALTH : PatchStatus.READY;
	}

	/**
	 * Whether a grown tree here is taken down by paying the gardener (or chopping it). Calquats and
	 * spirit trees are cleared with a spade instead, and a crystal tree is gone once harvested.
	 */
	boolean isRemovedForCoins()
	{
		return isTree() && this != CALQUAT && this != SPIRIT_TREE && this != CRYSTAL_TREE;
	}

	/**
	 * What the patch yields that the tool leprechaun can note; nothing for trees.
	 */
	Set<Integer> produce()
	{
		switch (this)
		{
			case HERB:
				return RunItems.HERBS_TO_NOTE;
			case ALLOTMENT:
				return RunItems.ALLOTMENT_PRODUCE;
			case FLOWER:
				return RunItems.FLOWER_PRODUCE;
			default:
				return Set.of();
		}
	}

	/**
	 * What taking the crop takes: an axe for celastrus bark and crystal shards, a spade for the rest.
	 */
	List<Integer> harvestItems()
	{
		return this == CELASTRUS || this == CRYSTAL_TREE ? RunItems.AXES : List.of(ItemID.SPADE);
	}

	/**
	 * What taking down a grown tree here takes.
	 */
	List<Integer> removalItems()
	{
		return isRemovedForCoins() ? List.of(ItemID.COINS) : List.of(ItemID.SPADE);
	}
}

package com.plugandplant;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup(PlugAndPlantConfig.GROUP)
public interface PlugAndPlantConfig extends Config
{
	String GROUP = "plugandplant";

	enum StopOrder
	{
		NEAREST("Nearest next"),
		RECOMMENDED("Recommended order");

		private final String label;

		StopOrder(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	enum ChecklistOverlayMode
	{
		NEVER("Never"),
		DURING_RUN("During a run"),
		ALWAYS("Always");

		private final String label;

		ChecklistOverlayMode(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	// What a run includes; hidden here as it is set in the side panel, right before a run
	// Settings from before run presets, read once to make the first presets
	String COMPOST_STEP = "compostStep";
	String ALLOTMENTS = "allotments";
	String FLOWERS = "flowers";
	String GRACEFUL = "graceful";
	String VOLCANIC_ASH = "volcanicAsh";
	String PROTECT_TREES = "protectTrees";
	/**
	 * The kind of run the side panel shows.
	 */
	String RUN_TYPE = "runType";
	String ALWAYS_SHOW = "alwaysShow";
	String NEVER_SHOW = "neverShow";

	@ConfigSection(
		name = "Overlays",
		description = "What is drawn in the game",
		position = 1
	)
	String overlaySection = "overlays";

	@ConfigSection(
		name = "Bank",
		description = "The bank filter",
		position = 2
	)
	String bankSection = "bank";

	@ConfigSection(
		name = "Routing",
		description = "How Shortest Path is asked for routes",
		position = 3
	)
	String routingSection = "routing";

	@ConfigItem(
		keyName = "highlightPatches",
		name = "Highlight patches",
		description = "During a run, draw a box over each patch that needs something, coloured and labelled by the next step",
		position = 1,
		section = overlaySection
	)
	default boolean highlightPatches()
	{
		return true;
	}

	@ConfigItem(
		keyName = "highlightItems",
		name = "Highlight inventory items",
		description = "During a run, highlight the inventory items the patches you are at need next, such as seeds to plant or compost",
		position = 2,
		section = overlaySection
	)
	default boolean highlightItems()
	{
		return true;
	}

	@ConfigItem(
		keyName = "checklistOverlay",
		name = "Checklist box",
		description = "When to show the in-game box with the checklist and the steps at your current location",
		position = 3,
		section = overlaySection
	)
	default ChecklistOverlayMode checklistOverlay()
	{
		return ChecklistOverlayMode.DURING_RUN;
	}

	@ConfigItem(
		keyName = "checklistMissingOnly",
		name = "Only list what is not carried",
		description = "Leave items you already carry out of the in-game checklist box, so it shows only what is left to withdraw",
		position = 4,
		section = overlaySection
	)
	default boolean checklistMissingOnly()
	{
		return true;
	}

	@ConfigItem(
		keyName = "filterBank",
		name = "Filter bank during run",
		description = "Show only farm run items, in sections, when you open the bank during a run. Needs the Bank Tags plugin.",
		position = 1,
		section = bankSection
	)
	default boolean filterBank()
	{
		return true;
	}

	@ConfigItem(
		keyName = ALWAYS_SHOW,
		hidden = true,
		name = "Always show",
		description = "Items to always show in the bank filter, by name or item ID, separated by commas or new lines."
			+ " Names ignore case, and * matches any text, so \"Ring of dueling*\" covers every charge.",
		position = 3,
		section = bankSection
	)
	default String alwaysShow()
	{
		return "";
	}

	@ConfigItem(
		keyName = NEVER_SHOW,
		hidden = true,
		name = "Never show",
		description = "Items to leave out of the bank filter even when a run needs them, written the same way as"
			+ " Always show.",
		position = 4,
		section = bankSection
	)
	default String neverShow()
	{
		return "";
	}

	@ConfigItem(
		keyName = "bankTeleports",
		name = "Teleports in bank filter",
		description = "Include the teleports you picked in the panel for the locations left to visit in the bank filter",
		position = 2,
		section = bankSection
	)
	default boolean bankTeleports()
	{
		return true;
	}

	@ConfigItem(
		keyName = "stopOrder",
		name = "Stop order",
		description = "Nearest next: route to whichever stop left is quickest to reach from where you are. "
			+ "Recommended order: visit the stops in the order of the OSRS Wiki's farming run guides.",
		position = 0,
		section = routingSection
	)
	default StopOrder stopOrder()
	{
		return StopOrder.NEAREST;
	}

	@ConfigItem(
		keyName = "bankDetourForSeeds",
		name = "Bank detour for seeds",
		description = "Have Shortest Path route through a bank when you don't carry a herb seed for the next stop. Ignored while you carry a seed box.",
		position = 1,
		section = routingSection
	)
	default boolean bankDetourForSeeds()
	{
		return true;
	}

	@ConfigItem(
		keyName = "carriedTeleportsOnly",
		name = "Route with carried teleports only",
		description = "During a run, have Shortest Path only use teleport items you are carrying, so the route follows the teleports you chose to bring. Turn off to use your own Shortest Path setting.",
		position = 2,
		section = routingSection
	)
	default boolean carriedTeleportsOnly()
	{
		return true;
	}
}

