			row.teleport.setFont(FontManager.getRunescapeSmallFont());
			row.teleport.setForeground(NEUTRAL);
			row.teleport.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			row.teleport.setBorder(new EmptyBorder(0, 0, 0, 0));
