				box.setBackground(ColorScheme.DARKER_GRAY_COLOR);
				box.setToolTipText("Untick to leave " + type.getPluralName().toLowerCase() + " at " + location.getDisplayName()
					+ " out of this run");
				box.addActionListener(e ->
