package com.plugandplant;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * A run preset's options, chosen in the side panel before a run.
 */
@Getter
@RequiredArgsConstructor
enum RunOption
{
	COMPOST("Compost", "Compost each patch you plant, while you carry compost"),
	PROTECT("Pay gardeners",
		"Pay each gardener to protect the tree you plant. The checklist and bank filter show the payment each sapling takes."),
	NOTE_HERBS("Note herbs",
		"Once the herb patch is replanted, use your herbs on the tool leprechaun to note them before the next patch"),
	NOTE_ALLOTMENTS_AND_FLOWERS("Note allotments & flowers",
		"Note allotment and flower produce at the tool leprechaun too. Leave it off to compost them instead."),
	GRACEFUL("Graceful", "Add the graceful outfit to the checklist and the bank filter"),
	VOLCANIC_ASH("Volcanic ash", "Add volcanic ash to the checklist and the bank filter");

	private final String label;
	private final String description;

	/**
	 * Whether the option means anything for the run: paying gardeners takes trees, noting herbs takes herbs.
	 */
	boolean appliesTo(RunPreset preset)
	{
		switch (this)
		{
			case PROTECT:
				return preset.includesTrees();
			case NOTE_HERBS:
				return preset.includes(PatchType.HERB);
			case NOTE_ALLOTMENTS_AND_FLOWERS:
				return preset.includes(PatchType.ALLOTMENT) || preset.includes(PatchType.FLOWER);
			default:
				return true;
		}
	}

	boolean isOn(RunPreset preset)
	{
		switch (this)
		{
			case COMPOST:
				return preset.isCompost();
			case PROTECT:
				return preset.isProtect();
			case NOTE_HERBS:
				return preset.isNoteHerbs();
			case NOTE_ALLOTMENTS_AND_FLOWERS:
				return preset.isNoteAllotmentsAndFlowers();
			case GRACEFUL:
				return preset.isGraceful();
			default:
				return preset.isVolcanicAsh();
		}
	}

	RunPreset set(RunPreset preset, boolean on)
	{
		switch (this)
		{
			case COMPOST:
				return preset.withCompost(on);
			case PROTECT:
				return preset.withProtect(on);
			case NOTE_HERBS:
				return preset.withNoteHerbs(on);
			case NOTE_ALLOTMENTS_AND_FLOWERS:
				return preset.withNoteAllotmentsAndFlowers(on);
			case GRACEFUL:
				return preset.withGraceful(on);
			default:
				return preset.withVolcanicAsh(on);
		}
	}
}

package com.plugandplant;

import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.annotation.Nullable;
import lombok.Value;

/**
 * What is left to do at a run's stops: the next step at each patch that needs one.
 *
 * A location is a stop because one of its anchor patches needs attention: the herb patch on a herb
 * run, the trees on a tree run. On a herb run, allotments and flower patches are tended along the
 * way while the player carries the seeds to replant them.
 */
@Value
class RunPlan
{
	/**
	 * The player's choices that shape the plan.
	 */
	@Value
	static class Options
	{
		RunPreset preset;
		/**
		 * Whether composting is a step, which takes the player carrying compost.
		 */
		boolean compost;
		/**
		 * Whether paying a gardener to protect a newly planted tree is a step.
		 */
		boolean protect;
		/**
		 * The player's Farming level, boosts included, which decides the Farming Guild patches they can reach.
		 */
		int farmingLevel;
		/**
		 * The kinds of patch whose produce is noted at the tool leprechaun as a step.
		 */
		Set<PatchType> noted;

		Options(RunPreset preset, boolean compost, boolean protect, int farmingLevel, Set<PatchType> noted)
		{
			this.preset = preset;
			this.compost = compost;
			this.protect = protect;
			this.farmingLevel = farmingLevel;
			this.noted = noted;
		}

		Options(RunPreset preset, boolean compost, boolean protect, int farmingLevel)
		{
			this(preset, compost, protect, farmingLevel, Set.of());
		}

		/**
		 * Whether the run tends the patch: one of the kinds it covers, within the player's reach.
		 */
		boolean includes(FarmPatch patch)
		{
			return preset.role(patch) != PatchRole.OFF && patch.getFarmingLevel() <= farmingLevel;
		}
	}

	/**
	 * Whether a contract for the type is grown on the run: one with trees for a tree, otherwise one with
	 * seed patches, even if it doesn't tend that kind of patch itself.
	 */
	static boolean covers(RunPreset preset, PatchType contractType)
	{
		return contractType.isTree() ? preset.includesTrees() : preset.includesSeedPatches();
	}

	/**
	 * Patches with something to do, stop by stop.
	 */
	Map<FarmPatch, Step> steps;
	/**
	 * The patches among {@link #steps} that still need seeds, now or after the current step.
	 */
	Set<FarmPatch> toPlant;
	/**
	 * The patches among {@link #steps} that still get compost, now or after the current step.
	 */
	Set<FarmPatch> toCompost;
	/**
	 * The trees whose gardener still gets paid, now or after the current step: those among
	 * {@link #steps}, and any planted on this run that the player has no payment for.
	 */
	Set<FarmPatch> toPay;
	/**
	 * Trees planted on this run whose gardener can be paid now, with the payment to hand. Paying
	 * doesn't wait on compost, so these are ready for the gardener whatever the patch's own step is.
	 */
	Set<FarmPatch> payable;
	/**
	 * The seed or sapling set aside from what the player carries for each patch in {@link #toPlant}
	 * that got one.
	 */
	Map<FarmPatch, Integer> seedsFor;
	/**
	 * Patches that have to be planted with one seed in particular: the crop of a farming contract.
	 */
	Map<FarmPatch, Integer> contractSeeds;
	/**
	 * Allotment and flower patches left out because the player doesn't carry the seeds to replant them.
	 */
	Set<FarmPatch> withoutSeeds;

	/**
	 * The stops with something left to do, in the order they were planned.
	 */
	Set<FarmLocation> targets()
	{
		Set<FarmLocation> targets = new LinkedHashSet<>();
		for (FarmPatch patch : steps.keySet())
		{
			targets.add(patch.getLocation());
		}
		return targets;
	}

	boolean hasSteps(FarmLocation location)
	{
		for (FarmPatch patch : steps.keySet())
		{
			if (patch.getLocation() == location)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * How many seeds of a kind the rest of the run takes.
	 */
	int seedsNeeded(PatchType type)
	{
		int patches = 0;
		for (FarmPatch patch : toPlant)
		{
			if (patch.getType() == type)
			{
				patches++;
			}
		}
		return patches * type.getSeedsPerPatch();
	}

	int count(Step step)
	{
		int count = 0;
		for (Step planned : steps.values())
		{
			if (planned == step)
			{
				count++;
			}
		}
		return count;
	}

	boolean has(Step step)
	{
		return steps.containsValue(step);
	}

	/**
	 * Works out the plan.
	 *
	 * @param stops           the locations to plan for, in the order seeds are handed out: the one
	 *                        the player is at first
	 * @param states          every patch's state
	 * @param composted       patches whose current crop, or bare soil, has been treated with compost
	 * @param protectedTrees  trees whose gardener has been paid to protect them
	 * @param justPlanted     patches planted earlier on this run that the player is still standing by,
	 *                        which can still be composted and paid for
	 * @param carried         what the player has on them, which decides the allotments and flowers they can replant
	 * @param contract        the player's farming contract, if it is for a crop a run grows
	 */
	static RunPlan of(List<FarmLocation> stops, Map<FarmPatch, PatchState> states, Set<FarmPatch> composted,
		Set<FarmPatch> protectedTrees, Set<FarmPatch> justPlanted, Options options, Carried carried,
		@Nullable FarmingContract contract)
	{
		Map<FarmPatch, Step> steps = new LinkedHashMap<>();
		Set<FarmPatch> toPlant = new LinkedHashSet<>();
		Set<FarmPatch> toCompost = new LinkedHashSet<>();
		Set<FarmPatch> toPay = new LinkedHashSet<>();
		Set<FarmPatch> payable = new LinkedHashSet<>();
		Map<FarmPatch, Integer> seedsFor = new HashMap<>();
		Map<FarmPatch, Integer> contractSeeds = new HashMap<>();
		Set<FarmPatch> withoutSeeds = new LinkedHashSet<>();

		// A contract is grown on the run of its kind
		Set<FarmPatch> contractPatches = new HashSet<>();
		if (contract != null && covers(options.getPreset(), contract.getType()))
		{
			for (FarmPatch patch : contract.patches(options.getPreset().includes(contract.getType())))
			{
				if (patch.getFarmingLevel() <= options.getFarmingLevel())
				{
					contractPatches.add(patch);
				}
			}
		}
		// A seed box the game hasn't shown the contents of is taken to hold whatever the player needs
		boolean seedBox = carried.isSeedBoxUnknown();
		Map<Integer, Integer> seedsLeft = new HashMap<>(carried.getItems());
		int spiritSlots = spiritSlots(states, options.getFarmingLevel());

		for (FarmLocation location : stops)
		{
			for (FarmPatch patch : location.getPatches())
			{
				boolean contractPatch = contractPatches.contains(patch);
				if (!contractPatch && !options.includes(patch))
				{
					continue;
				}

				PatchStatus status = states.getOrDefault(patch, PatchState.UNKNOWN).getStatus();
				if (takesSpiritSlot(patch, status))
				{
					if (spiritSlots <= 0)
					{
						continue;
					}
					spiritSlots--;
				}
				boolean replant = status.leadsToReplanting();
				if (replant)
				{
					List<Integer> seeds = contractPatch ? List.of(contract.getSeed()) : patch.getType().getSeeds();
					Integer seed = take(seedsLeft, seeds, patch.getType().getSeedsPerPatch());
					if (seed != null)
					{
						seedsFor.put(patch, seed);
					}
					// The anchor patches are why the location is a stop, and a contract is a commitment, so
					// those are planned whatever is carried; other patches only while seeds last
					boolean anchor = options.getPreset().role(patch) == PatchRole.VISIT;
					if (seed == null && !seedBox && !anchor && !contractPatch)
					{
						withoutSeeds.add(patch);
						continue;
					}
				}

				boolean needsCompost = options.isCompost() && !composted.contains(patch);
				boolean needsPayment = options.isProtect() && patch.getType().isProtectable() && !protectedTrees.contains(patch);
				// The gardener can only be paid with the payment to hand; without it the tree goes unprotected
				Sapling tree = states.getOrDefault(patch, PatchState.UNKNOWN).getCrop();
				boolean canPay = tree != null && tree.canPay(carried);
				if (needsPayment && canPay && status == PatchStatus.GROWING && justPlanted.contains(patch))
				{
					payable.add(patch);
				}
				Step step = step(status, needsCompost, needsPayment && canPay, justPlanted.contains(patch));
				// A patch's produce is noted as its last step, before going on to the next patch with room to spare
				if (step == null && justPlanted.contains(patch) && options.getNoted().contains(patch.getType())
					&& location.hasToolLeprechaun() && carried.unnoted(patch.getType().produce()) > 0)
				{
					step = Step.NOTE;
				}
				if (step == null)
				{
					// Planted on this run without the payment to hand: nothing to do, but the checklist says what's missing
					if (needsPayment && status == PatchStatus.GROWING && justPlanted.contains(patch))
					{
						toPay.add(patch);
					}
					continue;
				}

				steps.put(patch, step);
				if (replant)
				{
					toPlant.add(patch);
				}
				// Whatever ends in planting, or was just planted, still gets its compost and payment
				boolean fresh = replant || status == PatchStatus.GROWING;
				if (needsCompost && fresh)
				{
					toCompost.add(patch);
				}
				if (needsPayment && fresh)
				{
					toPay.add(patch);
				}
				if (contractPatch)
				{
					contractSeeds.put(patch, contract.getSeed());
				}
			}
		}

		return new RunPlan(
			Collections.unmodifiableMap(steps),
			Collections.unmodifiableSet(toPlant),
			Collections.unmodifiableSet(toCompost),
			Collections.unmodifiableSet(toPay),
			Collections.unmodifiableSet(payable),
			Collections.unmodifiableMap(seedsFor),
			Collections.unmodifiableMap(contractSeeds),
			Collections.unmodifiableSet(withoutSeeds));
	}

	/**
	 * How many spirit trees the game lets a player have planted at once at a Farming level.
	 */
	static int spiritTreeLimit(int farmingLevel)
	{
		if (farmingLevel >= 99)
		{
			return Integer.MAX_VALUE;
		}
		if (farmingLevel >= 96)
		{
			return 4;
		}
		if (farmingLevel >= 93)
		{
			return 3;
		}
		if (farmingLevel >= 88)
		{
			return 2;
		}
		return farmingLevel >= 83 ? 1 : 0;
	}

	/**
	 * How many more spirit trees the player may plant, as the game caps how many stand at once.
	 */
	static int spiritSlots(Map<FarmPatch, PatchState> states, int farmingLevel)
	{
		int limit = spiritTreeLimit(farmingLevel);
		if (limit == Integer.MAX_VALUE)
		{
			return limit;
		}
		int standing = 0;
		for (Map.Entry<FarmPatch, PatchState> state : states.entrySet())
		{
			if (state.getKey().getType() == PatchType.SPIRIT_TREE && holdsTree(state.getValue().getStatus()))
			{
				standing++;
			}
		}
		return limit - standing;
	}

	/**
	 * Whether tending the patch means planting a spirit tree where none stands, which is only worth
	 * the trip while the player may plant another.
	 */
	static boolean takesSpiritSlot(FarmPatch patch, PatchStatus status)
	{
		return patch.getType() == PatchType.SPIRIT_TREE && status.needsVisit() && !holdsTree(status);
	}

	/**
	 * Whether a living tree stands in the patch, which counts towards the spirit tree limit.
	 */
	private static boolean holdsTree(PatchStatus status)
	{
		switch (status)
		{
			case GROWING:
			case DISEASED:
			case CHECK_HEALTH:
			case GROWN:
				return true;
			default:
				return false;
		}
	}

	/**
	 * Sets aside enough of any one kind of seed for a patch.
	 *
	 * @return the seed set aside, or null if there weren't enough
	 */
	@Nullable
	private static Integer take(Map<Integer, Integer> seedsLeft, List<Integer> seeds, int perPatch)
	{
		for (int seed : seeds)
		{
			int left = seedsLeft.getOrDefault(seed, 0);
			if (left >= perPatch)
			{
				seedsLeft.put(seed, left - perPatch);
				return seed;
			}
		}
		return null;
	}

	@Nullable
	private static Step step(PatchStatus status, boolean needsCompost, boolean needsPayment, boolean justPlanted)
	{
		switch (status)
		{
			case READY:
				return Step.HARVEST;
			case CHECK_HEALTH:
				return Step.CHECK_HEALTH;
			case GROWN:
				return Step.REMOVE;
			case STUMP:
				return Step.DIG;
			case DEAD:
				return Step.CLEAR;
			case DISEASED:
				return Step.CURE;
			case WEEDS:
				return Step.RAKE;
			case EMPTY:
				return needsCompost ? Step.COMPOST : Step.PLANT;
			case GROWING:
				// Compost can also go on after planting, which is the order many players use; the
				// gardener is paid once the tree is in
				if (!justPlanted)
				{
					return null;
				}
				if (needsCompost)
				{
					return Step.COMPOST;
				}
				return needsPayment ? Step.PAY : null;
			default:
				return null;
		}
	}
}

package com.plugandplant;

import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import lombok.Value;
import lombok.With;
import net.runelite.api.coords.WorldPoint;

/**
 * A run the player has set up: what it does with each kind of patch, which locations and patches it
 * leaves out, and its options. A herb run and a tree run are made for every player to start with.
 */
@Value
@With
class RunPreset
{
	static final String HERB_ID = "herb";
	static final String TREE_ID = "tree";

	/**
	 * The patch types a run can cover, in the order the side panel lists them.
	 */
	static final List<PatchType> TYPES = List.of(PatchType.HERB, PatchType.FLOWER, PatchType.ALLOTMENT, PatchType.TREE,
		PatchType.FRUIT_TREE, PatchType.HARDWOOD_TREE, PatchType.CALQUAT, PatchType.SPIRIT_TREE, PatchType.CELASTRUS,
		PatchType.REDWOOD, PatchType.CRYSTAL_TREE);

	String id;
	String name;
	Map<PatchType, PatchRole> roles;
	/**
	 * Locations the player has left out of the run entirely.
	 */
	Set<FarmLocation> disabledLocations;
	/**
	 * Kinds of patch left out at a particular location, such as the fruit tree at the Farming Guild.
	 */
	Map<FarmLocation, Set<PatchType>> excludedTypes;
	boolean compost;
	boolean protect;
	boolean graceful;
	boolean volcanicAsh;
	/**
	 * Whether harvested herbs are taken to the tool leprechaun to be noted before moving on.
	 */
	boolean noteHerbs;
	/**
	 * Whether allotment and flower produce is noted too, which some players compost instead.
	 */
	boolean noteAllotmentsAndFlowers;

	static RunPreset herbRun()
	{
		return new RunPreset(HERB_ID, "Herb run", roles(PatchType.HERB, PatchRole.VISIT), Set.of(), Map.of(),
			true, true, false, false, false, false);
	}

	static RunPreset treeRun()
	{
		Map<PatchType, PatchRole> roles = roles(PatchType.TREE, PatchRole.VISIT);
		roles.put(PatchType.FRUIT_TREE, PatchRole.VISIT);
		return new RunPreset(TREE_ID, "Tree run", Collections.unmodifiableMap(roles), Set.of(), Map.of(),
			true, true, false, false, false, false);
	}

	private static Map<PatchType, PatchRole> roles(PatchType type, PatchRole role)
	{
		Map<PatchType, PatchRole> roles = new EnumMap<>(PatchType.class);
		for (PatchType each : TYPES)
		{
			roles.put(each, PatchRole.OFF);
		}
		roles.put(type, role);
		return roles;
	}

	/**
	 * What the run does with a kind of patch, wherever it is.
	 */
	PatchRole role(PatchType type)
	{
		return roles.getOrDefault(type, PatchRole.OFF);
	}

	/**
	 * What the run does with a particular patch, taking the location's own choices into account.
	 */
	PatchRole role(FarmPatch patch)
	{
		return isExcluded(patch.getLocation(), patch.getType()) ? PatchRole.OFF : role(patch.getType());
	}

	boolean isExcluded(FarmLocation location, PatchType type)
	{
		return excludedTypes.getOrDefault(location, Set.of()).contains(type);
	}

	boolean includes(PatchType type)
	{
		return role(type) != PatchRole.OFF;
	}

	boolean includesTrees()
	{
		return TYPES.stream().anyMatch(type -> type.isTree() && includes(type));
	}

	/**
	 * The kinds of patch whose produce the run notes at the tool leprechaun.
	 */
	Set<PatchType> notedTypes()
	{
		Set<PatchType> noted = EnumSet.noneOf(PatchType.class);
		if (noteHerbs && includes(PatchType.HERB))
		{
			noted.add(PatchType.HERB);
		}
		for (PatchType type : List.of(PatchType.ALLOTMENT, PatchType.FLOWER))
		{
			if (noteAllotmentsAndFlowers && includes(type))
			{
				noted.add(type);
			}
		}
		return noted;
	}

	/**
	 * Whether the run covers patches that take seeds rather than saplings.
	 */
	boolean includesSeedPatches()
	{
		return includes(PatchType.HERB) || includes(PatchType.FLOWER) || includes(PatchType.ALLOTMENT);
	}

	boolean isEnabled(FarmLocation location)
	{
		return !disabledLocations.contains(location);
	}

	/**
	 * The patches that make the location a stop when they need attention, within the player's reach.
	 */
	List<FarmPatch> anchors(FarmLocation location, int farmingLevel)
	{
		List<FarmPatch> anchors = new ArrayList<>();
		for (FarmPatch patch : location.getPatches())
		{
			if (role(patch) == PatchRole.VISIT && patch.getFarmingLevel() <= farmingLevel)
			{
				anchors.add(patch);
			}
		}
		return anchors;
	}

	List<FarmPatch> anchors(FarmLocation location)
	{
		return anchors(location, Integer.MAX_VALUE);
	}

	/**
	 * The kinds of patch the run covers at a location, before the location's own choices.
	 */
	List<PatchType> typesAt(FarmLocation location)
	{
		List<PatchType> types = new ArrayList<>();
		for (PatchType type : TYPES)
		{
			if (includes(type) && location.getPatches().stream().anyMatch(patch -> patch.getType() == type))
			{
				types.add(type);
			}
		}
		return types;
	}

	/**
	 * The locations with a patch of a kind the run covers, in the order the run visits them.
	 */
	List<FarmLocation> locations()
	{
		List<FarmLocation> locations = new ArrayList<>();
		for (FarmLocation location : recommendedOrder())
		{
			if (!typesAt(location).isEmpty())
			{
				locations.add(location);
			}
		}
		return locations;
	}

	/**
	 * Every location in the order of the OSRS Wiki's farming run guides: the tree run's order for a
	 * run that only visits for trees, otherwise the herb run's, with the tree run's other locations after.
	 */
	List<FarmLocation> recommendedOrder()
	{
		boolean treesOnly = includesTrees() && role(PatchType.HERB) != PatchRole.VISIT
			&& role(PatchType.FLOWER) != PatchRole.VISIT && role(PatchType.ALLOTMENT) != PatchRole.VISIT;
		Set<FarmLocation> order = new LinkedHashSet<>();
		if (treesOnly)
		{
			order.addAll(FarmLocation.TREE_ORDER);
			order.addAll(FarmLocation.HERB_ORDER);
		}
		else
		{
			order.addAll(FarmLocation.HERB_ORDER);
			order.addAll(FarmLocation.TREE_ORDER);
		}
		for (FarmLocation location : FarmLocation.values())
		{
			order.add(location);
		}
		return new ArrayList<>(order);
	}

	/**
	 * Where the run goes to at a location: its first anchor patch.
	 */
	WorldPoint pointFor(FarmLocation location)
	{
		List<FarmPatch> anchors = anchors(location);
		return (anchors.isEmpty() ? location.getPatches() : anchors).get(0).getPoint();
	}

	/**
	 * The run as a lower-case noun for messages, such as "herb run".
	 */
	String noun()
	{
		return name.isEmpty() ? "run" : Character.toLowerCase(name.charAt(0)) + name.substring(1);
	}

	RunPreset withRole(PatchType type, PatchRole role)
	{
		Map<PatchType, PatchRole> changed = new EnumMap<>(PatchType.class);
		changed.putAll(roles);
		changed.put(type, role);
		return withRoles(Collections.unmodifiableMap(changed));
	}

	RunPreset withLocationEnabled(FarmLocation location, boolean enabled)
	{
		Set<FarmLocation> changed = EnumSet.noneOf(FarmLocation.class);
		changed.addAll(disabledLocations);
		if (enabled)
		{
			changed.remove(location);
		}
		else
		{
			changed.add(location);
		}
		return withDisabledLocations(Collections.unmodifiableSet(changed));
	}

	RunPreset withExcluded(FarmLocation location, PatchType type, boolean excluded)
	{
		Map<FarmLocation, Set<PatchType>> changed = new EnumMap<>(FarmLocation.class);
		changed.putAll(excludedTypes);
		Set<PatchType> types = EnumSet.noneOf(PatchType.class);
		types.addAll(excludedTypes.getOrDefault(location, Set.of()));
		if (excluded)
		{
			types.add(type);
		}
		else
		{
			types.remove(type);
		}
		if (types.isEmpty())
		{
			changed.remove(location);
		}
		else
		{
			changed.put(location, Collections.unmodifiableSet(types));
		}
		return withExcludedTypes(Collections.unmodifiableMap(changed));
	}
}

package com.plugandplant;

import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import net.runelite.api.gameval.ItemID;

/**
 * What stands in for elemental runes: combination runes, and staves and tomes that supply them.
 */
final class Runes
{
	/**
	 * Combination rune to the two elemental runes it counts as.
	 */
	static final Map<Integer, Set<Integer>> COMBINATIONS = Map.of(
		ItemID.MISTRUNE, Set.of(ItemID.AIRRUNE, ItemID.WATERRUNE),
		ItemID.DUSTRUNE, Set.of(ItemID.AIRRUNE, ItemID.EARTHRUNE),
		ItemID.SMOKERUNE, Set.of(ItemID.AIRRUNE, ItemID.FIRERUNE),
		ItemID.MUDRUNE, Set.of(ItemID.WATERRUNE, ItemID.EARTHRUNE),
		ItemID.STEAMRUNE, Set.of(ItemID.WATERRUNE, ItemID.FIRERUNE),
		ItemID.LAVARUNE, Set.of(ItemID.EARTHRUNE, ItemID.FIRERUNE)
	);

	/**
	 * Staff or tome to the runes it supplies while equipped. Ornamented and other variants of these
	 * are mapped to them before looking up.
	 */
	private static final Map<Integer, Set<Integer>> SUPPLIERS = new HashMap<>();

	static
	{
		supplies(Set.of(ItemID.AIRRUNE),
			ItemID.STAFF_OF_AIR, ItemID.AIR_BATTLESTAFF, ItemID.MYSTIC_AIR_STAFF);
		supplies(Set.of(ItemID.WATERRUNE),
			ItemID.STAFF_OF_WATER, ItemID.WATER_BATTLESTAFF, ItemID.MYSTIC_WATER_STAFF, ItemID.KODAI_WAND, ItemID.TOME_OF_WATER);
		supplies(Set.of(ItemID.EARTHRUNE),
			ItemID.STAFF_OF_EARTH, ItemID.EARTH_BATTLESTAFF, ItemID.MYSTIC_EARTH_STAFF, ItemID.TOME_OF_EARTH);
		supplies(Set.of(ItemID.FIRERUNE),
			ItemID.STAFF_OF_FIRE, ItemID.FIRE_BATTLESTAFF, ItemID.MYSTIC_FIRE_STAFF, ItemID.TOME_OF_FIRE);
		supplies(Set.of(ItemID.AIRRUNE, ItemID.WATERRUNE), ItemID.MIST_BATTLESTAFF, ItemID.MYSTIC_MIST_BATTLESTAFF);
		supplies(Set.of(ItemID.AIRRUNE, ItemID.EARTHRUNE), ItemID.DUST_BATTLESTAFF, ItemID.MYSTIC_DUST_BATTLESTAFF);
		supplies(Set.of(ItemID.AIRRUNE, ItemID.FIRERUNE), ItemID.SMOKE_BATTLESTAFF, ItemID.MYSTIC_SMOKE_BATTLESTAFF);
		supplies(Set.of(ItemID.WATERRUNE, ItemID.EARTHRUNE), ItemID.MUD_BATTLESTAFF, ItemID.MYSTIC_MUD_STAFF);
		supplies(Set.of(ItemID.WATERRUNE, ItemID.FIRERUNE), ItemID.STEAM_BATTLESTAFF, ItemID.MYSTIC_STEAM_BATTLESTAFF,
			ItemID.TWINFLAME_STAFF);
		supplies(Set.of(ItemID.EARTHRUNE, ItemID.FIRERUNE), ItemID.LAVA_BATTLESTAFF, ItemID.MYSTIC_LAVA_STAFF);
	}

	private Runes()
	{
	}

	private static void supplies(Set<Integer> runes, int... itemIds)
	{
		for (int itemId : itemIds)
		{
			SUPPLIERS.put(itemId, runes);
		}
	}

	/**
	 * The runes an equipped item supplies.
	 *
	 * @param baseItemId the item, mapped from any variant to its base item
	 */
	static Set<Integer> suppliedBy(int baseItemId)
	{
		return SUPPLIERS.getOrDefault(baseItemId, Set.of());
	}
}

