	private RunPlan planNoting(List<FarmLocation> stops, Set<PatchType> noted, Map<Integer, Integer> unnoted,
		Set<FarmPatch> justPlanted)
	{
		RunPlan.Options options = new RunPlan.Options(Presets.herbs(true, true), false, false, 99, noted);
		return RunPlan.of(stops, states, Set.of(), Set.of(), justPlanted, options,
			new Carried(carried, Map.of(), Set.of(), Map.of(), false, unnoted), null);
	}

	private RunPlan planNoting(List<FarmLocation> stops, int herbs, Set<FarmPatch> justPlanted)
	{
		return planNoting(stops, Set.of(PatchType.HERB), Map.of(ItemID.UNIDENTIFIED_RANARR, herbs), justPlanted);
	}

	@Test
	public void herbsAreNotedOnceThePatchIsReplanted()
	{
		List<FarmLocation> stops = List.of(FarmLocation.FALADOR);
		set(FALADOR_HERB, PatchStatus.READY);
		assertEquals(Step.HARVEST, planNoting(stops, 5, Set.of()).getSteps().get(FALADOR_HERB));

		// Harvested: planting comes first, so the walk to the leprechaun is made once
		set(FALADOR_HERB, PatchStatus.EMPTY);
		assertEquals(Step.PLANT, planNoting(stops, 5, Set.of()).getSteps().get(FALADOR_HERB));

		// Planted: the herbs are noted while standing by the patch, grimy or cleaned
		set(FALADOR_HERB, PatchStatus.GROWING);
		assertEquals(Step.NOTE, planNoting(stops, 5, Set.of(FALADOR_HERB)).getSteps().get(FALADOR_HERB));
		assertEquals(Step.NOTE, planNoting(stops, Set.of(PatchType.HERB), Map.of(ItemID.RANARR_WEED, 3), Set.of(FALADOR_HERB))
			.getSteps().get(FALADOR_HERB));
		assertNull(planNoting(stops, 0, Set.of(FALADOR_HERB)).getSteps().get(FALADOR_HERB));
		// A herb patch left growing from before the run isn't a reason to stop
		assertNull(planNoting(stops, 5, Set.of()).getSteps().get(FALADOR_HERB));
	}

	@Test
	public void eachPatchsProduceIsNotedOnceItIsReplanted()
	{
		List<FarmLocation> stops = List.of(FarmLocation.FALADOR);
		set(FALADOR_HERB, PatchStatus.GROWING);
		set(FALADOR_ALLOTMENT_1, PatchStatus.GROWING);
		set(FALADOR_ALLOTMENT_2, PatchStatus.GROWING);
		set(FALADOR_FLOWER, PatchStatus.READY);
		carried.put(ItemID.MARIGOLD_SEED, 1);
		Set<FarmPatch> planted = Set.of(FALADOR_HERB, FALADOR_ALLOTMENT_1, FALADOR_ALLOTMENT_2);
		Set<PatchType> everything = Set.of(PatchType.HERB, PatchType.ALLOTMENT, PatchType.FLOWER);

		// The herbs are noted before the flower is harvested, so there is room for it; the allotments'
		// potatoes have been noted already
		RunPlan plan = planNoting(stops, everything, Map.of(ItemID.UNIDENTIFIED_RANARR, 5), planted);
		assertEquals(Map.of(FALADOR_HERB, Step.NOTE, FALADOR_FLOWER, Step.HARVEST), plan.getSteps());

		// Potatoes still on hand are noted at the allotments they came from
		RunPlan potatoes = planNoting(stops, everything, Map.of(ItemID.POTATO, 9), planted);
		assertEquals(Step.NOTE, potatoes.getSteps().get(FALADOR_ALLOTMENT_1));
		assertEquals(Step.NOTE, potatoes.getSteps().get(FALADOR_ALLOTMENT_2));
		assertNull(potatoes.getSteps().get(FALADOR_HERB));

		// Produce the run doesn't note, kept for the compost bin, is left alone
		assertNull(planNoting(stops, Set.of(PatchType.HERB), Map.of(ItemID.POTATO, 9), planted).getSteps().get(FALADOR_ALLOTMENT_1));
	}

	@Test
	public void herbsAreNotedOnlyWhenTheRunNotesThem()
	{
		// Troll Stronghold's leprechaun lies in a deckchair on the roof
		FarmPatch trollHerb = FarmLocation.TROLL_STRONGHOLD.patches(PatchType.HERB).get(0);
		set(trollHerb, PatchStatus.GROWING);
		assertEquals(Step.NOTE, planNoting(List.of(FarmLocation.TROLL_STRONGHOLD), 5, Set.of(trollHerb)).getSteps().get(trollHerb));

		set(FALADOR_HERB, PatchStatus.GROWING);
		assertNull(planNoting(List.of(FarmLocation.FALADOR), Set.of(), Map.of(ItemID.UNIDENTIFIED_RANARR, 5), Set.of(FALADOR_HERB))
			.getSteps().get(FALADOR_HERB));
	}
}

package com.plugandplant;

import com.google.gson.Gson;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class RunPresetTest
{
	private static final FarmPatch GUILD_HERB = FarmLocation.FARMING_GUILD.patches(PatchType.HERB).get(0);
	private static final FarmPatch GUILD_FLOWER = FarmLocation.FARMING_GUILD.patches(PatchType.FLOWER).get(0);
	private static final FarmPatch GUILD_TREE = FarmLocation.FARMING_GUILD.patches(PatchType.TREE).get(0);
	private static final FarmPatch GUILD_FRUIT_TREE = FarmLocation.FARMING_GUILD.patches(PatchType.FRUIT_TREE).get(0);

	private static RunPlan plan(RunPreset preset, PatchStatus status, FarmPatch... ready)
	{
		Map<FarmPatch, PatchState> states = new HashMap<>();
		for (FarmPatch patch : ready)
		{
			states.put(patch, new PatchState(status, 0));
		}
		return RunPlan.of(List.of(FarmLocation.FARMING_GUILD), states, Set.of(), Set.of(), Set.of(),
			new RunPlan.Options(preset, false, false, 99), Carried.NOTHING, null);
	}

	@Test
	public void theDefaultsAreAHerbRunAndATreeRun()
	{
		assertEquals(List.of(GUILD_HERB), Presets.HERBS.anchors(FarmLocation.FARMING_GUILD));
		assertEquals(List.of(GUILD_TREE, GUILD_FRUIT_TREE), Presets.TREES.anchors(FarmLocation.FARMING_GUILD));
		assertFalse(Presets.HERBS.includesTrees());
		assertTrue(Presets.TREES.includesTrees());
	}

	@Test
	public void aRunCanVisitForHerbsAndTreesAlike()
	{
		RunPreset both = Presets.HERBS.withRole(PatchType.TREE, PatchRole.VISIT);

		assertEquals(List.of(GUILD_HERB, GUILD_TREE), both.anchors(FarmLocation.FARMING_GUILD));
		assertEquals(Set.of(GUILD_HERB, GUILD_TREE), plan(both, PatchStatus.READY, GUILD_HERB, GUILD_TREE).getSteps().keySet());
		// Trees and herbs together keep the herb run's order, with the tree locations after
		assertEquals(FarmLocation.FALADOR, both.locations().get(0));
		assertTrue(both.locations().contains(FarmLocation.LUMBRIDGE));
	}

	@Test
	public void aKindOfPatchCanBeLeftOutAtOneLocation()
	{
		RunPreset noGuildFruitTree = Presets.TREES.withExcluded(FarmLocation.FARMING_GUILD, PatchType.FRUIT_TREE, true);

		assertEquals(List.of(GUILD_TREE), noGuildFruitTree.anchors(FarmLocation.FARMING_GUILD));
		assertEquals(Set.of(GUILD_TREE), plan(noGuildFruitTree, PatchStatus.CHECK_HEALTH, GUILD_TREE, GUILD_FRUIT_TREE).getSteps().keySet());
		// Only there
		assertEquals(PatchRole.VISIT, noGuildFruitTree.role(FarmLocation.CATHERBY_ORCHARD.patches(PatchType.FRUIT_TREE).get(0)));
		assertEquals(Presets.TREES, noGuildFruitTree.withExcluded(FarmLocation.FARMING_GUILD, PatchType.FRUIT_TREE, false));
	}

	@Test
	public void flowersVisitedForAreAnchorsButTendedOnesAreNot()
	{
		RunPreset tend = Presets.HERBS.withRole(PatchType.FLOWER, PatchRole.TEND);
		RunPreset visit = Presets.HERBS.withRole(PatchType.FLOWER, PatchRole.VISIT);

		assertEquals(List.of(GUILD_HERB), tend.anchors(FarmLocation.FARMING_GUILD));
		assertTrue(visit.anchors(FarmLocation.FARMING_GUILD).contains(GUILD_FLOWER));
		// Tended flowers need seeds; ones visited for are planned whatever is carried
		assertTrue(plan(tend, PatchStatus.READY, GUILD_FLOWER).getSteps().isEmpty());
		assertEquals(Set.of(GUILD_FLOWER), plan(visit, PatchStatus.READY, GUILD_FLOWER).getSteps().keySet());
	}

	@Test
	public void aDisabledLocationIsRememberedPerPreset()
	{
		RunPreset withoutGuild = Presets.HERBS.withLocationEnabled(FarmLocation.FARMING_GUILD, false);

		assertFalse(withoutGuild.isEnabled(FarmLocation.FARMING_GUILD));
		assertTrue(Presets.TREES.isEnabled(FarmLocation.FARMING_GUILD));
		assertEquals(Presets.HERBS, withoutGuild.withLocationEnabled(FarmLocation.FARMING_GUILD, true));
	}

	@Test
	public void presetsAreSavedAndReadBack()
	{
		RunPreset custom = Presets.HERBS.withId("custom-1").withName("Everything")
			.withRole(PatchType.TREE, PatchRole.VISIT)
			.withRole(PatchType.FLOWER, PatchRole.TEND)
			.withLocationEnabled(FarmLocation.WEISS, false)
			.withExcluded(FarmLocation.FARMING_GUILD, PatchType.TREE, true)
			.withRole(PatchType.CALQUAT, PatchRole.VISIT)
			.withGraceful(true)
			.withNoteHerbs(true)
			.withNoteAllotmentsAndFlowers(true);

		assertEquals(custom, PresetStore.roundTrip(new Gson(), custom));
	}

	@Test
	public void optionsFollowThePreset()
	{
		assertFalse(RunOption.PROTECT.appliesTo(Presets.HERBS));
		assertTrue(RunOption.PROTECT.appliesTo(Presets.TREES));
		assertTrue(RunOption.GRACEFUL.isOn(RunOption.GRACEFUL.set(Presets.HERBS, true)));
		assertTrue(RunOption.NOTE_HERBS.appliesTo(Presets.HERBS));
		assertFalse(RunOption.NOTE_HERBS.appliesTo(Presets.TREES));
		assertTrue(RunOption.NOTE_HERBS.isOn(RunOption.NOTE_HERBS.set(Presets.HERBS, true)));
		assertFalse(RunOption.NOTE_ALLOTMENTS_AND_FLOWERS.appliesTo(Presets.HERBS));
		assertTrue(RunOption.NOTE_ALLOTMENTS_AND_FLOWERS.appliesTo(Presets.herbs(true, false)));

		// Allotments and flowers are noted only with their own option, as their produce may go to the compost bin
		RunPreset all = Presets.herbs(true, true).withNoteHerbs(true);
		assertEquals(Set.of(PatchType.HERB), all.notedTypes());
		assertEquals(Set.of(PatchType.HERB, PatchType.ALLOTMENT, PatchType.FLOWER),
			all.withNoteAllotmentsAndFlowers(true).notedTypes());
	}
}
